/* 2015年11月30日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h27-20151130-9","dateIso":"2015-11-30","title":"2015年11月30日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4870#one","fetchedAt":"2026-08-14","characters":88305,"voices":[{"i":1,"speaker":"塚本委員長","text":"○午前１０時００分開会\nただいまより、文教委員会を開会いたします。\n本日は、お手元の審査・調査予定表のとおり、議案審査、請願・陳情審査、その他と進めてまいります。\nなお、本日は議案の中途議決のため、午後０時３０分から議会運営委員会、午後１時から本会議が開催されます。そのため、午前１１時を目途に委員会を休憩し、本会議終了後、すぐに委員会を再開する予定でございます。\n本日も効率的な委員会運営にご協力をお願いいたします。\n────────────────────────────────────────────\n１ 議案審査\n(8) 第１１５号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例\n(9) 第１１６号議案 学校教育職員の給与に関する条例の一部を改正する条例"},{"i":2,"speaker":"塚本委員長","text":"それでは、予定表１、議案審査を行います。\n初めに、本日の議案審査の進め方について、ご案内いたします。(8)第１１５号議案および(9)第１１６号議案につきまして、午後１時からの本会議で中途議決が予定されておりますため、先にこの２議案の審査を行います。２議案の審査終了後、(1)第８８号議案の審査を行いますが、質疑の途中であっても、午前１１時を目処に委員会を一度休憩させていただき、午後１時からの本会議が終了次第、委員会を再開し、引き続き議案審査を行ってまいります。\n再開後の進め方といたしまして、(1)第８８号議案が審議途中であった場合、その続きを行います。\n(2)第８９号議案は、義務教育学校にかかる改正がございますので、先に(3)第９０号議案の審査を行います。第９０号議案が可決いたしましたら、(4)第９１号議案の審査、次に(2)第８９号議案と(6)第９３号議案を一括して審査をいたします。\nその後は、(5)第９２号議案の審査、(7)第９７号議案の審査、(10)第８４号議案の審査と進めてまいりたいと思いますので、よろしくお願いいたします。\nそれでは、(8)第１１５号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例、および(9)第１１６号議案、学校教育職員の給与にかかる条例の一部を改正する条例を一括して議題に供します。\n本件２議案につきまして、関連する内容のため、一括して説明、質疑を行い、その後、議案ごとに採決を行いたいと思いますので、よろしくお願いいたします。\n本件につきまして、理事者より一括してご説明願います。"},{"i":3,"speaker":"渋谷指導課長","text":"それでは、第１１５号議案ならびに第１１６号議案についてご説明申し上げます。\n両案は本年１０月１３日に行われました特別区人事委員会勧告を踏まえ、幼稚園教育職員および区固有教員の給与に関し、所要の改正を行うものでございます。そのほかの区の職員全体にかかわる部分、また勧告制度の仕組み等につきましては、総務委員会での審査となります。\n改正の内容といたしましては、まず、給料表でございますが、幼稚園教育職員につきましては、特別区人事委員会勧告に基づき、公民較差分、月額給与１,４１３円、率にして０.３５％の解消を図るため、全体として引上げ改定を行うものでございます。\n次に、学校教育職員、こちらは区固有教員にかかるものでございますが、こちらにつきましても特別区人事委員会勧告に基づき、東京都人事委員会勧告に沿った改正を行うこととし、公民較差分、月例給４８０円、率にして０.１２％の解消を図るため、全体として引上げ改定を行うものでございます。\n続きまして、扶養手当の改正でございます。こちらは、幼稚園教育職員および学校教育職員共通のものでございますが、国、他の地方公共団体および民間との比較結果や、国における少子化対策の推進などの観点から、扶養親族である子等にかかる手当の月額を５００円引き上げ、これまでの５,５００円から６,０００円に改定するものであります。\nなお、給料表および扶養手当の改定につきましては、本年４月支給の給与よりさかのぼって適用することとしております。\n続きまして、特別給の年間支給月数の改定でございます。こちらにつきましても、幼稚園教育職員および学校教育職員に共通するものでございますが、特別区人事委員会勧告に基づき、特別給の年間支給月数を現行の４.２０月から４.３０月に０.１月分引き上げるものであります。今回の引上げ分につきましては、民間の支給状況を勘案し、その全てを勤勉手当に割り当てることとしております。\n最後に、両条例の施行日につきましては、公布の日から施行することとし、給料表および扶養手当にかかる改正規定は、平成２７年４月１日より適用いたします。"},{"i":4,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":5,"speaker":"飯沼委員","text":"条例の第３０条の第２項中というところからの説明、これは勤勉手当なのですけれども、この１００分の８０が１００分の９０にという改定がどういう意味をしているのか、勤勉手当の中身で、数字で申しわけないのですけれども、教えていただきたい。\n条例の付則のところに書いてある切替日とはどういう中身なのか、意味を教えてください。"},{"i":6,"speaker":"渋谷指導課長","text":"確認なのですけれども、１点目の１００分の何とかというのは、どこに書いてあるのですか。"},{"i":7,"speaker":"飯沼委員","text":"条例文のところです。新旧対照表のところに書いてあるのですが、第１１５号議案の大もとのところです。新旧のところです。"},{"i":8,"speaker":"渋谷指導課長","text":"すみません。そこは後ほど確認させていただければと思います。\n２点目の切替日というのは。"},{"i":9,"speaker":"飯沼委員","text":"はい。切替日とはどういう意味。条例文の付則のところに書いてあるのです。文言がわからないので教えてください。"},{"i":10,"speaker":"渋谷指導課長","text":"まず、切替日については、施行日の前日までの間における異動者の号給ということで、条例の施行される日にちが平成２７年４月１日からになるという日程ということでございます。\nそれから、１００分の９０というのは、給与月額に１００分の９０を掛けた額が限度額になっているというものを定めた比率ということでございます。"},{"i":11,"speaker":"飯沼委員","text":"こういう書き方をして、この範囲ですよというものがもともと決まっているのが、１００分の８０が９０になったということなのですね。あまりよくわからないのですけれども、少し難しいことを聞いてしまって申しわけありません。\nあと、総務委員会で聞くのかもしれないのですが、Ａ４の説明の裏側の期末手当ではなくて、今回は勤勉手当で０.１月を支給するということで、その時々によって、きっと話し合いで決まると思うのですが、期末手当ではなくて勤勉手当になることの影響はあるのですか。大もとのところで申しわけないのですが。"},{"i":12,"speaker":"塚本委員長","text":"お答えできますか。"},{"i":13,"speaker":"渋谷指導課長","text":"影響というのは、支給を受ける側にすると、期末手当であれば一律固定でありますが、勤勉手当はいわゆる業績給になりますので、その人によって若干影響はあるというところでございます。"},{"i":14,"speaker":"飯沼委員","text":"わかりました。ありがとうございます。"},{"i":15,"speaker":"浅野委員","text":"今回の職員の給与改定についてということですが、細かいところはなかなか難しいものがありまして、理解できているとは、私も到底自分では言えないと思うのですけれども、総額の幼稚園教育職員の給与、また学校教育職員の給与が全体でそれぞれどのくらい上がるのか。全体でそれぞれを教えていただければと思います。"},{"i":16,"speaker":"渋谷指導課長","text":"これは、１人当たりということでよろしいでしょうか。全体。"},{"i":17,"speaker":"浅野委員","text":"総額です。"},{"i":18,"speaker":"渋谷指導課長","text":"給料と扶養手当の改定による影響としては、幼稚園、固有教員で、見込みですけれども、６９万４,５９６円。それから、勤勉手当の支給月数による改定の影響額としては、幼稚園教諭３７名分、固有教員２０名分で２１１万８,６５７円ということで、予算として差額として増えるのが２８１万３,２５３円ということでございます。"},{"i":19,"speaker":"浅野委員","text":"２８０万円強、全体で年間に上がるということです。これは、毎年のように改正されていると思うのですけれども、大体２００万円から３００万円近く毎年上がっていくというイメージなのでしょうか。これは教員の数にもよると思うのですけれども、総じてどのような流れに毎年なっているのかということの概略を教えてください。"},{"i":20,"speaker":"渋谷指導課長","text":"人事委員会勧告がプラスのときには、その割合に応じて、若干額の変動があるということでございます。今回の人事委員会勧告の補正によって、今２８０万円余のお金が必要になってくるのですが、実際のところ、幼稚園の教諭で２名、育児休業になっていたり、固有教員でも２名が育児休業になっていて、その分、給料が支払われなかったりするので、差し引きすると給与の予算として足りなくなるということはないので、改めてそこで補正を組んだりする措置はしなくても済むということで、飲み込めるという形になります。"},{"i":21,"speaker":"浅野委員","text":"概略的なところをお伺いしたのですけれども、さまざま要因があって、変化はしていると思います。民間に対してどうなのかとか、そういう流れの中で、やはり適正な賃金にされていくという流れだと思いますので、その点については了解いたしました。"},{"i":22,"speaker":"塚本委員長","text":"ほかにございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":23,"speaker":"塚本委員長","text":"では、ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、本件２議案に対する各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":24,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":25,"speaker":"浅野委員","text":"賛成します。"},{"i":26,"speaker":"飯沼委員","text":"賛成します。"},{"i":27,"speaker":"大倉委員","text":"賛成です。"},{"i":28,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":29,"speaker":"塚本委員長","text":"それでは、これより２議案につきまして、１件ずつ採決を行ってまいります。\nまず、第１１５号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":30,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n次に、第１１６号議案、学校教育職員の給与に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":31,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n３ その他\n(2) 委員長報告について"},{"i":32,"speaker":"塚本委員長","text":"冒頭申し上げましたとおり、本日は中途議決が予定されておりますので、予定表３、その他の(2)委員長報告についてを先に議題に供しますので、ご了承くださいますようお願いいたします。\nただいま行いました第１１５号議案および第１１６号議案の２議案の審査の結果報告につきましては、正副委員長にご一任いただきたいと思いますが、よろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":33,"speaker":"塚本委員長","text":"ありがとうございます。\nそれでは、正副委員長でまとめさせていただきますので、よろしくお願いいたします。\n────────────────────────────────────────────\n１ 議案審査\n(1) 第８８号議案 品川区立保育所条例の一部を改正する条例"},{"i":34,"speaker":"塚本委員長","text":"引き続き、議案審査を行います。\n(1)第８８号議案、品川区立保育所条例の一部を改正する条例を議題に供します。\n本件につきまして、理事者より一括して説明願います。"},{"i":35,"speaker":"今井待機児童対策担当課長","text":"それでは、第８８号議案、品川区立保育所条例の一部を改正する条例についてご説明申し上げます。既に配付してございます委員会資料を用いまして説明させていただきます。\nこれまで、本文教委員会におきましては、広町二丁目大規模保育施設としまして、５月に計画、７月に施設の運営を委託する事業者の報告をさせていただいているところでございます。\nそれでは、委員会資料の１番と２番、１の改正の背景および改正の理由についてでございますが、区では総合的な待機児童対策により、明日１２月１日に開設します、くりのき保育園を含め、平成２２年度から平成２７年度までの６年間に３,６２４人の保育受入枠を拡大しております。一方、乳幼児人口および認可保育園の入園申込者数の増加によりまして、保育需要は高まっているところでございます。\nそのため、子ども・子育て計画策定時よりも、さらに対策を強化し、区有地を活用した大規模保育施設の開設を行うものです。\nなお、本区有地は、広町地区の再開発などを踏まえ、暫定施設として５年間を目途として開設することおよび緊急対策として平成２８年４月の開設に間に合うよう、整備を進める必要があったことから、公設民営の区立保育園として開設するに至ったところでございます。\n３、４の改正内容および施設概要でございます。３の改正内容につきましては、条例第１条別表に新設した施設の名称と所在地を加えるもので、４の施設概要にありますとおり、その名称は品川区立ひろまち保育園、設置者は品川区、運営事業者は社会福祉法人夢工房、開設地である所在地は広町二丁目１番１８号、開設日は平成２８年４月１日、保育園の延床面積は約１,７３６m2でございます。\n定員につきましては、１歳から２歳が１０２人、３歳から５歳が１９８人、合計３００人で、年齢別の内訳につきましては、１歳児が４８人、２歳児が５４人、３歳から５歳児クラスは各６６人でございます。\n次に、基本開所時間でございますが、７時半から１８時半まで、時間外保育時間は１８時半から１９時半までとしております。\nなお、本施設につきましては、暫定施設であることから、１２月１日に配布します保育園のご案内において、暫定施設として平成２８年４月から平成３３年３月までの５年間の目処ですが、転園する際は在園児の受入先を確保いたしますとの注記をする予定でございます。\n次に、裏面をお願いいたします。５の新旧対照表でございます。左側の新の欄にありますとおり、別表に施設の名称を品川区立ひろまち保育園、所在地を東京都品川区広町二丁目１番１８号と加えるものでございます。\nまた、６の施行期日につきましては、開設予定日と同日の同年平成２８年４月１日に施行するものでございます。\n本条例議案につきまして、ご審議のほど、よろしくお願いいたします。"},{"i":36,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":37,"speaker":"飯沼委員","text":"今回は５年間の暫定ということなのですけれども、設置の条例については、５年間とか書くところはないのですね。その点が１点です。\nあと今回、公設民営ということなのですけれども、指定管理者と委託の違いを教えてください。"},{"i":38,"speaker":"今井待機児童対策担当課長","text":"まず１点目に、こちらは施設の名称と所在地を記載するものでございますので、期間の記載は必要ございません。\nそれから、公設民営につきまして、指定管理と委託の違いということでございます。こちらは、業務委託というのは、品川区で仕様を確定いたしまして、その内容に基づいて事業者に運営経費を支払うものでございます。例えば、開所時間等につきましても、品川区でこれから規則で定めてまいりますが、そういう内容を定めるものでございます。\nそれから、指定管理につきましては、指定管理者を公設施設の受託ということで、公の施設の管理権限ということで、それぞれの条例で定めて、使用許可等も含めまして、事業者に包括的に業務を委託するものでございます。"},{"i":39,"speaker":"飯沼委員","text":"今回、区立の保育園を新たに設置するということで、本当に待機児童が増えている中で、父母の皆様と喜んでいるのですけれども、今回、公設民営委託という手法は初めてですね。公設民営で委託は多分初めてかと捉えているのですけれども、今、指定管理との違いもお聞きしました。なぜ直営でしないのか。どうして民営なのか。この点に関して、非常に残念な思いをしているのですけれども、なぜ委託の手法をとるのかというところをお答えいただきたいと思います。"},{"i":40,"speaker":"今井待機児童対策担当課長","text":"委員ご案内のとおり、品川区で平成２２年から保育園の株式会社立等の開設を進めてまいりましたけれども、それに先立って、国では多様な設置主体によりまして、待機児童対策を進めていこうという中では、これだけ社会福祉法人だけではなく、株式会社も保育園開設に向けて事業を進めておりますので、ここで民設民営という形で、私立の保育園で進めていくという方針に変わりはございません。\nただし、ここの施設につきましては、今年の補正で議決いただきましたとおり、とにかく待機児童が増える４月の中で、来年の４月に向けて開設する必要があったことから、建物は区立という形で進めたところでございます。\nそれに伴いまして、なぜ委託かということでございますけれども、品川区のリースという形で、最後、解体までする形で進めてまいりますので、そういう面では指定管理者制度にはなじまないものだと考えております。"},{"i":41,"speaker":"飯沼委員","text":"質問の本旨は、なぜ品川区の直営で、品川区が運営する保育園にならなかったのかというところなので、そこのところをもう一回お答えいただきたいのと、あと、開所時間のところなのです。１９時３０分というところで、ここがどういう経過でこの時間になったのかという判断をお聞かせください。"},{"i":42,"speaker":"今井待機児童対策担当課長","text":"初めに、なぜ区立ではないのかということですけれども、品川区は今、新規開設については、民間事業者等の活力を得ながら進めていくという方針ですので、まずは民間事業者の活力を得る方法から検討して進めたところでございます。\n２点目、午後７時半までの時間外保育でございますけれども、やはり暫定施設ということがございますので、品川区内、区立、私立とも、皆様午後７時半までは開設しておりますので、もしこちらが廃園に至ったときに、スムーズに移行できるということも考えて、午後７時半と考えております。"},{"i":43,"speaker":"飯沼委員","text":"なぜ区立でないのかというところは、明日、「区立保育園の今後の運営について」という報告があるので、そこでじっくりとご意見を伺いたいなと思っています。民間の活力を得るというところなのですけれども、やはり日本各地で民営化の問題点がいっぱい起こっていますし、本当に大事な品川区内の子どもたちを、自治体が責任を持って直営でやっていくという姿勢が、やはり子育てのところでは一番大事ではないかと思っていますので、明日、またそこは意見を述べたいと思っています。\n開所時間は、次への移行というのももちろんそうなのですが、駅から近いこともあるし、大体この辺で大丈夫だろうといった判断があったのかなと思うのですけれども、もう一回、その点はいかがでしょうか。"},{"i":44,"speaker":"今井待機児童対策担当課長","text":"まず、私ども、これを検討するにあたりましては、やはり今後の移行のスムーズなところも第一点でございましたけれども、委員ご案内のとおり、午後７時半というのは、お迎えが大体午後７時ぐらいまでのところでピークを迎えますので、適切な時間だと思っております。\nまた、近隣に品川保育園等も午後１０時まで開園の園等もございますので、駅近だけではなく、全体の近隣の保育園とのバランスを見て決定したところでございます。"},{"i":45,"speaker":"浅野委員","text":"今回の保育所条例の一部改正で、本格始動ということで、いよいよ建設も進められて、４月スタートということで、動かれているのかと思います。本当にこれだけ大きい保育園ということになりますと、運営のほうも大変かなと思いつつも、しっかりとした準備をされているかと思いますので、事故のないように進めていただければと思います。\n大した質問ではないのですけれども、１つだけお伺いしたいことがあります。今回のひろまち保育園は４４番という番号がついているのですけれども、この番号の意味というのは、できた順番につけるのが普通かと思いつつ、例えば、途中で閉園した園や番号がついていた園が出た場合には、欠番にするのか、大した質問ではなくてすみませんけれども、そこら辺、どういう番号の運営になっているかというのを教えてください。後学のために。"},{"i":46,"speaker":"今井待機児童対策担当課長","text":"委員ご案内のとおり、こちらの条例の設置以降は、どんどん設置順番に付番しているわけですけれども、今、こういう形で区立の条例で規定する区立保育園が４４カ所あるという形で、もし１つ途中で廃園ということに至れば、番号が繰り上がるといいますか、全体の番号を示しているものですので、これが数という形で、欠番ではなくて、全部が繰り上がるような形で認識しております。\nただ、最終的にそういう事例がございませんので、そのように考えております。"},{"i":47,"speaker":"浅野委員","text":"多分、番号にも意味があるのだろうと私は思っているのです。やはり開園していて、その園が閉園した場合にはどうなるのかというのは、今、事例がないというお話なのでしょうか。そういう事例も、今後、もしかすると出てくる可能性もあるので、そこら辺のルールは区の中で統一のとれた考え方で進めていっていただいたほうがいいかと。削除するのか、番号を欠番にするのか、それとも、今言われたように全て繰り上がるのか、そういうことも考えられたらいいと思います。これは要望ということでお願いします。"},{"i":48,"speaker":"石田（ち）委員","text":"品川区立ひろまち保育園ということで、広町の字を平仮名にしたのは何でかなと、ただそれだけなのです。大体地域の名前がつく区立保育園はそういうところが多いと思うのですけれども、大体漢字なのですけれども、何で平仮名になったのか。誰が考えたのか、その点が疑問です。"},{"i":49,"speaker":"今井待機児童対策担当課長","text":"委員ご案内のとおり、基本的には町丁目の名前、五反田ですとか、そういうものがあるのですけれども、例えば、豊町にありますゆたか保育園は豊町保育園と言いませんで、平仮名で「ゆたか」となっております。わかりやすさという形も含めて、今回検討したものでございます。"},{"i":50,"speaker":"石田（ち）委員","text":"それで、３００人規模ということで、大変大きな保育園になっていると。父母の皆様からも大丈夫なのかという声がまだまだ聞こえてくるところなのですけれども、保育士、また働いている方々の確保状況は、保育士も集まりづらいという状況のもとで、何か聞いているでしょうか。伺いたいと思います。"},{"i":51,"speaker":"今井待機児童対策担当課長","text":"運営事業者である社会福祉法人夢工房が保育士の確保といいますか、採用を行っております。ご案内のとおり、ここの事業者を選定しました理由も、全国的に、または品川区の近隣の目黒区、港区でもう既に認可保育園を開設しているというところでございました。私どもも保育士の確保については、いろいろな情報共有をしておりますけれども、現在のところスムーズに行われていると聞いております。"},{"i":52,"speaker":"伊藤副委員長","text":"３つお伺いしたいのですけれども、１つは、前にお話をしていたのですが、通園の安全性の確保について。ここは、劇団四季の大型バスが入ったり、工場に来る人たちがいると思うのですけれども、その交通安全をどう確保したのかということ。\nそれから、ほかの地域であったことですけれども、地域に説明がほしいと。例えば、この場所で、こういう規模の保育園を開くにあたって、地域の町会長や商店街の会長なり、そういう話をしてほしいという話があったのですけれども、それを夢工房はなさったのでしょうかということの確認をお願いいたします。"},{"i":53,"speaker":"今井待機児童対策担当課長","text":"登降園の交通につきましては、どちらかというと、中に入るところを含めて、一般道というよりも中に入ってしまえば、ＪＲや劇団四季というところなのですけれども、これにつきましては、警備員ですね、制服を着ている。自転車での登園になりますので、警備事業者に委託をして対応していこうと考えております。\nまた、いろいろご指摘もいただきましたので、登園・降園ルートにつきましては、これから入園される方、保護者への保育の説明会の中でも細かく説明していきますし、自転車の駐輪などに関しましても、丁寧に説明をして、安全についてはご理解をいただくようにしてまいりたいと思っております。\nそれから、地域への説明でございますけれども、こちらは運営だけではなく、工事につきましても近隣の町会、商店街のほうへのご説明は済んでいるところでございます。"},{"i":54,"speaker":"伊藤副委員長","text":"交通安全のことは、そんなに難しいことではありませんけれども、ただ、子どもがゼロ歳から５歳までだから、ぜひ対応をお願いします。\nそれから、前にも聞いたのですけれども、５年ということはわかっているのですけれども、例えば、急転直下にＪＲとまとまって、この場所を再開発することになる可能性もあるわけではないですか。その場合に私たちが思うのは、開設はするのですけれども、既に保育園を開設していたとするなら、逆に交渉に有利な条件として、その施設をＪＲの施設の中に入れてもらうなり、そういうアイデアを持って交渉していくべきだと思うのだけれども、いかがでしょうか。"},{"i":55,"speaker":"今井待機児童対策担当課長","text":"初めに、登降園の交通につきましては、１歳児園という形で、あまりベビーバギーというのはないかなと思っているのですが、お子さんと自転車、または一緒に歩いて登園するような形になろうかと思います。改めまして、運営事業者と協議しながら、安全性を高めていきたいと思っております。\nそれから、今後の広町の開発に伴ってのご質問でございますけれども、こちらの広町の開発につきましては、保育園というのが実際にできたわけですけれども、一方では劇団四季のような品川区の集客施設もあることでございますので、駅前などの立地条件を踏まえまして、町内全体での議論になろうかと思っております。\n保育課としましては、ひろまち保育園があるということで、在園児の皆様への周知などを含めて、時期などについては十分配慮しながら進めていただくように所管と協議を進めたいと思います。"},{"i":56,"speaker":"伊藤副委員長","text":"おそらく、こういう条例を出してきたわけですから、ＪＲと相当協議をして、５年間動かないというある程度の確証があったからだと思うのですけれども、逆に言うと５年後に保育園をどうするか。そのときに、今まさに課長がおっしゃっているように、この再開発の話が具体的に展開するかによっては、やはりそれは品川区の庁舎全体として、これをいい交渉材料としてほしいと思うのです。せっかくあるわけですから、それは今のところ５年というのはわかるのだけれども、そのときの再開発の状況の中で、例えば、広域で建設できるとするならば、それは品川区全体として考えていくべきであるし、またそういう場合には、５年先、さらに延長していくことも考えられるだろうし、お願いしたいのは、広町の再開発の中にこの保育園を有意義に活用していただくことをお願いしたいと思うのですが、最後に一言お願いいたします。"},{"i":57,"speaker":"金子子ども未来部長","text":"ひろまち保育園が再開発の予定地内につくるということで、あらかじめ目途を５年ということで、保護者の皆様方には周知しなければならないということで明示しているわけです。再開発が、あらかじめ何が必要で、何が必要でないかということを明示するとなると、これは相手方のあることでなかなか難しい面も出てこようかと思います。\nただ、品川区の保育の受給事情というのが今後どうなるか、見通しが難しいところもあると思います。そういう意味では、そういうことも踏まえた上で、再開発というのは区として判断していかなければならないだろうと思っておりますので、今から確定的なことは申し上げにくいのですけれども、さまざまな状況を踏まえて対応していくことが必要かと考えております。"},{"i":58,"speaker":"高橋（し）委員","text":"まず、登園等の自転車の話が出たのですけれども、大井町の周辺の自転車置き場。保育園には置いていけないのだと思うのですけれども、そこは所管の方と、ひょっとするとお仕事される方で置いていく方が増えるのではないかと思うのですが、そこのあきが十分あるならばいいのですけれども、そのキャパの関係はどんな感じなのでしょうか。\nもう一つは、私が以前に議会でお話しし、確認を忘れたのかもしれませんが、５年より延長する可能性や、そういうことに関してはどういう表現で夢工房とお話をなさっているのでしょうか。例えば、現在、そういう条件が入っているのか、それともそういうことがあったときは、何年前かにどうこうという、５年が区切りだとすると、どういった表現になっているのか、２つお願いします。"},{"i":59,"speaker":"今井待機児童対策担当課長","text":"こちらの近隣の自転車駐輪場につきましては、既に交通安全担当課長とも情報共有しながら、近隣の状況を見ている中です。定期利用が大分利用されている中でございますので、早めに内定の方が４月以降に向けての定期利用の更新ができるように、情報提供は早めにしていきたいと思っております。\nそれ以外にも、一時利用できる自転車駐輪場を近隣には民間も含めて４カ所ございますので、そういう４カ所の駐輪場の情報自体を既に内定の段階でお示ししていくような考えでおります。\n２点目ですけれども、事業者に対して、５年間または延長の可能性につきましては、基本的には５年間で一定目処をつけるということは、事業者には申し伝えております。ただ、延長の可能性等につきましては、今後判断するという表現でございまして、一定の時期に品川区としても事業者、そして区民の方に周知していくという形でお約束していくということです。"},{"i":60,"speaker":"高橋（し）委員","text":"延長のほうは、今後判断するという表現で契約している。\nそれから、先ほどの自転車のほうは、定期利用はおそらく入っていないと思うので、一時利用を利用してくださいみたいな感じになると思うのですが、そのあたりは今お話あったように、ご利用される保護者の方にできるだけ早く自転車置き場はここだということをお伝えしないと、またそれはそれで交通安全のほうで自転車置き場がという話になってくるので、ぜひ連携をとっていただくようお願いします。"},{"i":61,"speaker":"石田（ち）委員","text":"もう一回だけ。園庭のことで伺いたかったのですけれども、屋外遊戯場で、近くの公園ということになってしまうのでしょうか。この間、ずっと園庭をと求めてきたのですけれども、ひろまち保育園ができる隣に駐車場だった場所があるので、そこを園庭に使えるだろうなと思いながら、私たちはずっと見ているのです。そういった考えはないでしょうか。"},{"i":62,"speaker":"今井待機児童対策担当課長","text":"園庭につきましては、以前から申し上げているとおり、中庭が約２００m2、６０坪以上の面積を持っておりますので、こちらで泥遊び等をしていただくという形で考えております。代替の遊戯場はしながわ中央公園を考えておりまして、隣接する駐車場につきましては、近隣の商店街からの要望等もございます。駐車場で引き続き活用していくという考えに変わりはございません。"},{"i":63,"speaker":"石田（ち）委員","text":"すると、近くのＪＲの土地だということで、なかなか難しいというお話も伺っていたのですけれども、土地はたくさんあるわけですけれども、ＪＲとの交渉などは、この間、園庭という形ではされてはいないということですか。そこを伺いたいと思います。"},{"i":64,"speaker":"今井待機児童対策担当課長","text":"ＪＲ東日本、劇団四季とは運営事業者を交えて、また品川区独自でいろいろ打ち合わせをしてきたところでございますけれども、この園庭につきましては、特に議題としては上っておりません。"},{"i":65,"speaker":"石田（ち）委員","text":"やはり園庭がある保育園にということで、父母の皆様からの要望が本当に多く届いているところですので、ぜひ今後も努力をしていただけたらと思うのですけれども、いかがでしょうか。"},{"i":66,"speaker":"今井待機児童対策担当課長","text":"このひろまち保育園の開設につきましては、ＪＲ東日本も１,０００人以上の方があちらで勤務されている状況もございますので、その状況等を踏まえまして、ＪＲが判断されているものでございます。私どもとしましては、ＪＲの考え方がございますので、そちらを園庭という形で要望する考えはございません。"},{"i":67,"speaker":"大倉委員","text":"確認で、こちらの夢工房はいろいろ認可保育園等も実績があってやられている中で、以前３００人規模の大きな園はまだやったことがないというお話だったと思うのですが、その後、３００人を受け入れるのはすごく大変だと思うので、その辺の運営がしっかりできるように区としてどういう話をしていったのかというところと、３００人の子どもが災害で何かあったときに、これも前回の話で出たかもしれないのですけれども、避難しなければいけないときというのは、かなり大変な避難になるのかなというところで、その辺がどうなっているか教えていただきたい。例えば、ＪＲと協議もいろいろされて、劇団四季ともという中で、そういった避難についてはどういう協議をされているか教えてください。"},{"i":68,"speaker":"今井待機児童対策担当課長","text":"保育の内容につきましては、基本的には運営事業者である夢工房が行うもので、特に夢工房からは、今まで打ち合わせをしている中では、やはり１歳児クラスですと２部屋ございますけれども、２部屋に限らず、その部屋を少しコーナー保育ができるように、少人数感を感じられるように保育をしていきたいというのも聞いております。\nそれから、避難でございますが、もともと区の他の場所と比べますと、広町というのは延焼するところではございませんので、基本的にはそこで待機という形の防災上の場所になります。ですので、避難といいますと、いろいろな災害が考えられるわけですけれども、その施設にきちんと備蓄品を持ちまして、そこで滞留といいますか、まずはそこで待機できるように努めますとともに、万が一、今議員ご心配の延焼ですとかといった場合には、避難について、事業者とまた細かく検討していきたいと思っております。現時点では、ここの地域は基本的には延焼の心配のない地域ということで、品川区としても事業者と協議をしているところです。"},{"i":69,"speaker":"塚本委員長","text":"ほかによろしいですか。\n〔「なし」と呼ぶ者あり〕"},{"i":70,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、本件に対する各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":71,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":72,"speaker":"浅野委員","text":"賛成します。"},{"i":73,"speaker":"飯沼委員","text":"一言だけ。直営でやっていただきたかったという希望はありますけれども、条例に対しては賛成いたします。"},{"i":74,"speaker":"大倉委員","text":"賛成です。"},{"i":75,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":76,"speaker":"塚本委員長","text":"それでは、これより、第８８号議案、品川区立保育所条例の一部を改正する条例について、採決をいたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":77,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n会議の運営上、暫時休憩いたします。\n○午前１０時４９分休憩\n○午後 １時１３分再開"},{"i":78,"speaker":"塚本委員長","text":"それでは、これより文教委員会を再開いたします。\n休憩中に４名の傍聴申請がございましたので、ご案内いたします。\n────────────────────────────────────────────\n(3) 第９０号議案 品川区立学校設置条例の一部を改正する条例"},{"i":79,"speaker":"塚本委員長","text":"(3)第９０号議案、品川区立学校設置条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして、理事者より説明願います。"},{"i":80,"speaker":"野呂瀬学務課長","text":"それでは、第９０号議案、品川区立学校設置条例の一部を改正する条例についてご説明いたします。\n学校教育法等の一部を改正する法律が、本年６月に公布され、現行の小学校、中学校に加え、小学校から中学校までの義務教育を一貫して行う義務教育学校が新たな校種、学校の種類として創設されました。この法律改正に伴い、区ではこれまでの小中一貫教育の成果を踏まえ、品川区立義務教育学校を新たに設置するために、学校設置条例を改正するものであります。\n改正の内容でございますが、資料１ページ、中段の表のとおり、義務教育学校６校を平成２８年４月１日付で設置いたします。\nなお、名称は今まで使っていた通称名が正式名となります。\nまた、義務教育学校の設置に伴い、施設一体型小中一貫校を構成している小学校６校、中学校６校については、平成２８年３月３１日をもって廃止といたします。\nなお、条例施行日は平成２８年４月１日といたします。\n新旧対照表でお示ししておりますが、条例施行後の区立学校数は小学校３１校、中学校９校、義務教育学校６校の計４６校となります。\nご審議のほど、よろしくお願いいたします。"},{"i":81,"speaker":"品川庶務課長","text":"続いて、私から補足でございますが、学校教育法の一部を改正する法律の概要についてご説明をいたしたいと思います。\nそれでは、資料をご覧いただきたいと思います。まず、簡単な法案の概要のほうから説明したいと思います。資料はこちらになります。\n(1)小中一貫教育を行う新たな学校の種類の制度化というところでございます。趣旨としましては、先ほど学務課長からも説明がありましたように、現行の小・中学校に加えて、小学校から中学校までの義務教育を一貫して行う義務教育学校を新たな学校の種類として規定しております。\nそれから、その下です。設置者・設置義務ということで、これは国立、公立、私立、いずれも設置は可能ということになっております。\nまた、市区町村につきましては、公立小・中学校の設置義務がありますので、義務教育学校の設置をもって、この設置の義務を履行することになっていることが書かれております。\n続きまして、３番目です。目標・修業年限とあります。こちらにつきましては、まず目標ですが、心身の発達に応じて、義務教育として行われる普通教育について、基礎的なものから一貫して施すこと。それから、修業年限でございますが、小学校、中学校をあわせて９年間。前期を６年、後期を３年と区分してございます。\nそれから、教職員の関係でございますが、こちらにつきましては、小学校と中学校の免許状の併有を原則とします。ただ、当分の間は例外の規定があります。例外というのは、小学校の免許を持っている先生につきましては、義務教育学校の前期課程、中学校の免許を持っている方については、後期課程ができるという規定になります。\nその下です。施設整備の面でございますが、こちらの学校の新築、または増築に要する経費は、現在の小・中学校でも同様に国の負担がついておりますが、義務教育学校につきましても、同じように国の補助がつくということで提供しているものでございます。\nそれから、下の図をご覧ください。義務教育学校のイメージということで、大きく分けて２種類となります。施設一体型の義務教育学校、それから、施設が分離している義務教育学校という形になります。\nこの法律の施行日でございますが、２番のところをご覧いただきますと、平成２８年４月１日から施行という形になってございます。\nそれでは、もう少し細かな説明をしたいと思いますので、資料の次ページをご覧いただきたいと思います。こちらの資料になります。\nそれでは、第１のところです。学校教育法の一部改正の概要ということでございます。まず１番目、義務教育学校の創設というところで、先ほど簡単なところは説明をいたしました。\nもう一つ、義務教育学校の名称というところをご覧いただきたいと思います。義務教育学校という名称は、法律上の学校の種類を示す名称でございますので、例えば学校名に「義務教育学校」と付さなければいけないものではないということが書いてございます。\nそれから、設置義務のところをご覧ください。設置義務の中の就学指定の対象というところをご覧いただきたいと思います。市区町村の義務教育学校は、就学指定の対象とする予定でございます。そういうことになりますので、入学者の選抜は行わないものであることと書いてあります。\nそれから、その下です。義務教育学校の目的でございます。義務教育学校を施す点につきましては、小・中学校と義務教育学校は同等であるという考えのもとに進めていくものでございます。\nそれから、義務教育学校の設置基準というところでございます。これは先ほどもご説明しましたように、前期課程については小学校の設置基準、後期課程につきましては、中学校の設置基準を準用することとなってございます。\nその下です。丸で書いてあります、義務教育学校の修業年限並びに前期課程及び後期課程の区分とございます。そのところで、学年の区分というところをご覧いただきたいと思います。２行目ぐらいになりますが、「４－３－２」や「５－４」など、柔軟な学年段階の区切りを設定することは可能であるとなっております。\nそれから、その下です。丸で書いてあります。前期課程及び後期課程の目的及び目標というところで、こちらも似たようなところになりますが、前期課程におきましては、小学校における教育と同一の目標を達成するもの。それから、後期課程については中学校における教育と同一の目標を達成するものというものが書かれております。\nページ裏面をご覧いただきたいと思います。第２と書いてあります、公立義務教育学校諸学校の学級編制及び教職員定数の標準に関する法律の一部改正等の概要というところがございます。ここにつきましては、公立の義務教育学校につきましては、学級編制、それから教職員の定数の標準につきましては、前期課程は現行の小学校、後期課程は現行の中学校と同等としております。\nそれから、次がポイントになりますが、最後のほうに載っています副校長または教頭を１人加算することとしております。ですので、義務教育学校１校に対して、校長先生が１人、副校長先生が３人という体制になるということが書いてございます。\nその他、第３につきましては、先ほどの学校の建設等にあたるときの補助金の関係が書いてございます。\nそれから、第４につきましては、教職員の免許の関係が書いてあります。\n第５につきましては、平成２８年４月１日が施行ですということを書いておりますので、先ほど説明しましたので、ここの部分は割愛させていただきます。"},{"i":82,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":83,"speaker":"石田（ち）委員","text":"今、説明をしていただいたのですけれども、品川区としては、何がどう変わっていくのか。何か国のほうで法改正ということだというご説明があったのですけれども、品川区では具体的にどんなふうに、何がどう変わるのか伺いたいと思います。"},{"i":84,"speaker":"野呂瀬学務課長","text":"何がどう変わるということなのですけれども、基本的には校名が変更になるというのは大きな変更点なのですけれども、今までやってきた児童・生徒に対しての負担や影響は、基本的にはないものと考えております。今まで従来行われてきた小中一貫教育が、今回法的にも制度的にも明確に位置づけられたと捉えているところでございます。"},{"i":85,"speaker":"石田（ち）委員","text":"校名の変更が一番大きな変更だということです。私も城南中学校に通っていたのですけれども、一貫校になっても校名は残るのだよということは、小中一貫校の説明のときに説明はされていたのですけれども、それが結局なくなってしまう。母校の名がなくなるということにおいて驚いたのですけれども、地域の皆様は本当に学校を大事に思って、いろいろ活動もされているのです。そういったところへの説明なり、そして声というのはどのように把握されているでしょうか。"},{"i":86,"speaker":"品川庶務課長","text":"まず、地域への周知でございますが、基本的には各連合町会の会長に関しては、学校長および教育委員会を通して説明をしているところでございます。\nそれから、各小中一貫校につきましては、地域に関連のある方、外部評価委員等に関しましても、校長から説明をしてございます。\nまた、１０月の上旬ぐらいに学校説明会を行ってございます。小中一貫校６校につきましては、学校説明会の中で、義務教育学校の説明もしているという状況でございます。"},{"i":87,"speaker":"石田（ち）委員","text":"そういった説明の中で、何か校名が変わってしまうということに関しての声が出ていたのかどうかというのをお答えいただきたいのと、これが法制化されて、義務教育学校になるということで、何で校名が変わっていかなければいけなくなるのかというのを教えていただきたいのです。"},{"i":88,"speaker":"品川庶務課長","text":"まず、声につきましては、小中一貫校、例を挙げれば日野学園につきましては、今年度で１０周年を迎えております。各校につきましても、小中一貫校で何々学園という名称で呼ばれている中で、学校名がなくなるということに関しての声というのは、特に教育委員会の中では聞いていないという状況でございます。\nそれから、学校名がなぜなくなるのかということでございますが、小学校、中学校、新たに義務教育学校という学校種が設定されます。この義務教育学校として名称を今回は「○○学園」という形で、小中一貫校に対しては６校設定をしてございますので、旧来は「小中一貫校○○学園」と言っておりましたが、学校教育法の中では、正式には小学校と中学校が２校あったという状況でございますが、今回の法改正によりまして１校という形になりましたので、名称はなくなるということでございます。"},{"i":89,"speaker":"石田（ち）委員","text":"施設分離型の学校も義務教育学校になっていくということですけれども、ここは当然そのままの名称が残る。これは変わらないということで確認させていただきます。"},{"i":90,"speaker":"品川庶務課長","text":"施設分離型の義務教育学校でございますが、今回につきましては、品川区の中で施設分離型の義務教育学校というのは設定をする予定はございません。あくまでも施設一体型の義務教育学校を６校やっていくということでございます。"},{"i":91,"speaker":"石田（ち）委員","text":"わかりました。\nこの小中一貫校が義務教育学校という新たな学校種になっていくというところでの変化は、学校名だと。私は、学校名のところは「残します」と言っていたのに、これがどんどん進んでいくにあたってなくなっていくという突然感といいますか、ショックなのですけれども、地域の方々からも少しずつそういった声が寄せられているのです。学校の名前というのは、区の判断で残していくというふうにはできないということなのですか。"},{"i":92,"speaker":"品川庶務課長","text":"今まで、法的に２校あった学校です。それを今回は１校にしていくということでございますので、残していくというのは２校の名前をそのまま１校に残すということはなかなか難しいところもあります。\nそれから、「○○学園」という名前も、かれこれ１０年間は区民の皆様にも非常になじんでもらっているということもありますので、前の学校名を残すというのは、２校を１校にするという中で、難しいことだと考えております。"},{"i":93,"speaker":"石田（ち）委員","text":"やはり学校名はすごく大事なものではないかと私は思っているのですけれども、城南中学校出身だ、品川小学校出身だ、そういったところで共通の話もできる。年を超えても、年齢差があっても、そういったところですごく親しみを持って話される共通したものだと思うので、それがなくなってしまうということについて、もう少し地域の声等を聞いていただきたいと思います。\nそれで、各連合町会長には説明をされたということですけれども、町会となかなかつながっていない区民も多くいる中で、校名がなくなる。なくなりますといったことを言わないにしても、やはり私も驚いたので、そういったところでの説明をしていただきたいと思います。\nそれと、義務教育学校になっていく。ずっと品川区が小中一貫校を先駆けて進めてきた。それが国にも認められて、法制化されてきたということを大きな成果として教育委員会は掲げているわけですけれども、前の文教委員会でも、所管事務調査のところで小中一貫校の成果ということが資料等も出されたのです。何が成果だったのか。学力が向上した、いじめがなくなった、こういったことがなかなかわかりづらいものなのですということを説明しておきながら、成果は何なのかということがわからない。それで、そのまま法制化されて義務教育学校になりましたと言われても、一貫校と一般の小・中学校を比較しての成果というものがどうあるのか伺いたいと思うのです。"},{"i":94,"speaker":"品川庶務課長","text":"初めの質問にお答えいたします。学校名がなくなることについて、声を聞く説明をしてほしいという提案でございますが、これは既に連合町会長等、校長先生、学校を通じまして説明会をしているところでございます。そういう中で、校名がなくなるということについても、説明はしていることでございますので、これに対して、現在のところ大きい声はございませんので、十分説明は果たしていると考えております。"},{"i":95,"speaker":"渋谷指導課長","text":"小中一貫校の成果というお話でございましたが、基本的に品川区は全区で小中一貫教育を進めておりまして、品川区の子どもたちは品川区小中一貫教育要領という一貫教育の例に基づいた教育をしているということで、特に施設一体型の一貫校が特別ずば抜けて成果があるというご説明はしていないかと思っております。"},{"i":96,"speaker":"石田（ち）委員","text":"ですが、国がこれを法制化していくところでの議論を見ていても、一貫校を進めてきた地域が取り上げられて、声も聞かれて、成果があるということで進められてきたものなのではないかと思いますので、教育的な効果やデメリットも本当に十分検証されて進められたものなのかというのを伺いたいのです。法制化についてです。"},{"i":97,"speaker":"渋谷指導課長","text":"法制化に向けて、あえてその部分で十分検討したかというと、それはもう既に小中一貫教育、施設一体型一貫校を１０年間やってきたという実績の中で、国の法制化が整ったので、そこに品川区も改めて正式に乗っかっていったという流れでございます。施設一体型一貫校の施設的な部分、ハード的な部分での成果等々をここで改めて検証したということではございません。"},{"i":98,"speaker":"石田（ち）委員","text":"そうすると、義務教育学校にしていく意味は何なのかと思うのです。だったら、今までのままでもいいではないですか。小中一貫校を進めてきた品川区ですから、それを法制化されたという上では、進めてきた先頭だとなってくるのだろうと思うのです。ですから、それを国よりも先に進めてきた品川区として、今の小中一貫校、これまでも検証してきたといったことで、この間も成果を資料で出していただいたのですけれども、それでも全然明確ではないと思ってきたので、そこをはっきりしないままに、いいものだといって進められるというのは、先ほども言いましたけれども、教育的効果のデメリットを十分に検証されていないのではないか。それで進んでいくものだと感じるのですけれども、その辺、品川区としてはいかがでしょうか。"},{"i":99,"speaker":"品川庶務課長","text":"今、まさに委員がおっしゃったことで、法改正が今回なされたということで、今まで小中一貫教育を長年進めてきた品川区が、新たにこういう義務教育学校という形で学校を設定していくということでございます。"},{"i":100,"speaker":"石田（ち）委員","text":"小中一貫校が進められていく中で、期待するものとして、学力の向上や学習意欲の向上ということがパンフレットなんかでもうたわれているのですけれども、前回の所管事務調査での資料を見せていただく中でも、１０年間やられていても、そこまで期待するものが表れていない。そういったところの検証がしっかりされてきたのかということを伺っているのです。お願いします。"},{"i":101,"speaker":"渋谷指導課長","text":"委員は誤解をされているようですけれども、小中一貫教育の成果と施設一体型の建物での成果ということは、明確に分けてお考えいただければと思います。品川区としては、学校選択制をしています。そういう中で、全ての品川区の小・中学校、いわゆる今までの施設一体型一貫校、均一の学校、義務教育の質の向上を目指して取り組んできているわけでございますので、そういう部分で成果があるというのが、まず１つです。\nそれから、施設一体型の一貫校、そういった形態の違うものがなぜということでございますが、単独の小学校、中学校でも、小規模校もあります、大規模校もあります。そういった地域の環境要件ですとか、その土地の問題だとか、そういった状況の中から学校選択制をしている品川区として、さまざまな学校の形態のものを用意して、保護者、地域の皆様の選択に耐え得るような条件を整えることの１つと考えられるのではないかと思っております。"},{"i":102,"speaker":"石田（ち）委員","text":"施設一体型の小中一貫校が今回義務教育学校になっていくということなので、それをどんどん進めてきた品川区として、私は検証が十分にされていないと思うのです。小中一貫校に期待するものということで掲げているものが、ことごとく向上していない、まだまだ課題だというところなのですけれども、そういう中で一気に進めていくというのが、本当に理解できないですし、不安です。\nそして、先ほど大規模校と小規模校という話もありましたけれども、大規模化が進んでいくという中でも、子どもへの影響だったり、教員数の問題だったり、いじめの問題、運動会の問題、生徒同士の問題等々、本当に対策の問題があって、私たちもこれを議論する中でもまとめ切れないぐらいにたくさんの課題がまだまだあるなと思うのです。そういう中で、法制化までして進めていくというメリットが私にはわからないのです。"},{"i":103,"speaker":"塚本委員長","text":"石田委員、これは今ある施設一体型の旧年型の小中一貫校が法制化されたので、その法制化にのっとって義務教育学校と位置づけられ得るものですから、位置づけたということが基本なので、そこにおいて、義務教育学校の中身がどうかというのは、今後とも議論されていくいろいろなことなので、それを踏まえた上で、そろそろ質問をまとめていただきたいと思います。"},{"i":104,"speaker":"石田（ち）委員","text":"今、委員長もおっしゃったように、法制化されたというところでは、品川区の経験はすごく参考にもされたし、品川区としてもいろいろ発信してきたと思うのですけれども、要は今まで私が言ったような問題や課題がまだまだある中で、なぜ進めていくのか。品川区が法制化するよりも前段階で進めてきた。だから、今を機に改めてまた検証していかなければいけないし、改善させていかなければいけないところがたくさんあると思いますので、法制化を機に、改めて教育的な効果やデメリットというのを、もっと発信していただきたいと思うのです。\n何度も言いますけれども、この間いただいた成果では全然わからなかったので、そういったところで、問題点と成果というものをもっと明らかにしていただきたいのですけれども、いかがでしょうか。"},{"i":105,"speaker":"渋谷指導課長","text":"これは、義務教育学校の法制化にかかわらず、教育の営みというのは、常にどの小学校段階でも、中学校段階でも、ましてや小中一貫教育でも、日々問題点、改善を図っていくという営みを我々はしているところでありますし、これからもきちんとそういったものについては、全ての教育活動において取り組んでいきたいと考えております。"},{"i":106,"speaker":"鈴木（博）委員","text":"教育委員会と品川区が、品川区の教育に意欲的にいろいろ想像と多様性と試みをして、子どものために新しくチャレンジするという姿勢は、非常によいことであり、それに関しては強く支持したいと思うのです。その成果の一環として、今回、文部科学省が学校教育法の改正ということを行ったと理解しているのです。\n今、法案の概要というのを読ませていただいたのですけれども、結局、小学校と中学校が前期と後期と分かれただけで、スタッフも教育課程も基本的には今までのものを踏襲しなさいと読めたのです。これは、品川区で今意欲的にやっている教育改革等で、若干ずれているのかもしれないのですけれども、結局、文部科学省が出した法案というのは、積極的にこれがいいから新しい概念の義務教育学校をつくるということがあまり読み取れなかったのです。この法案の中ではどこが、文部科学省が義務教育学校をつくるという積極的な意味づけを読み取ったらよろしいのでしょうか。"},{"i":107,"speaker":"渋谷指導課長","text":"積極的な意味づけというよりも、義務教育学校の法制化については、自治体、現場レベルでの実践が先行して、既に１０年たってきたということで、各地方自治体が主体的な意思を持ってやりたいことについて、法案としてお墨つきを与えたという解釈だと思っております。"},{"i":108,"speaker":"鈴木（博）委員","text":"そうすると、現場でやっているから、国としてそれに認可を与えるというスタンスでこの法律が出たのでしょうか。そうすると、あまり積極的な意味はないと思うのだけれども。"},{"i":109,"speaker":"渋谷指導課長","text":"積極的な意味合いというよりも、やはり実践をしている現場にとって、よりやりやすくなるようにという意味合いで法制化したと考えています。例えば、実際に教育課程の特例校という仕組みを使って、品川区は独自の市民科等をやらせていただいていますが、義務教育学校が法制化されたことによって、そういう手続を踏まなくてもできるようになるですとか、各種調査が一貫校については、小学校、中学校と別々に来ていたものが、今度は義務教育学校と法制化されることによって一本になるので、現場の事務軽減になったり、そういうことが国の法制化によってより進んで、我々の取組みが非常にやりやすくなってくるという捉え方をしております。"},{"i":110,"speaker":"鈴木（博）委員","text":"非常によくわかりました。要するに、現場でやっていることに国として応援するというスタンスの法律だということなのですね。\nそうすると、２枚目の「４－３－２」や「５－４」などの柔軟な学年段階の区切りを設定することも可能である。ただし、これは課程の変更を意味するものではなくて、カリキュラム編集上の工夫や指導上の重点を設けるための便宜的な区切りを設定することを想定しなさいと書いてあるのだけれども、これはどういうふうに読み取ったらいいのか。"},{"i":111,"speaker":"渋谷指導課長","text":"６年間で小学校段階での一定の修業が終わりますということについては変わりません。ですから、義務教育学校の６年が終わった段階で、場合によっては他の中学校に行ったりすることができる。その部分での「６－３」の枠組みはあります。ただ、勉強の中身を考えるときに、例えば品川区でやっているように、１年生から４年生までは基本的に学級担任制でやりながら、５年生から教科担任制を取り入れたりということは、各自治体の工夫の中で自由にやっていいですという意味合いのものでございます。"},{"i":112,"speaker":"鈴木（博）委員","text":"わかりました。\nそれと、日野学園なんかはもう１０年たっているのですけれども、うちの患者さんに聞いても、「僕は日野学園だ」と言う人がいても、「私は第二日野小学校だ」と言う人は１人もいませんから、その名前がかなり浸透していると現場では理解している人間もいるということを一言だけつけ加えておきます。"},{"i":113,"speaker":"浅野委員","text":"今回の義務教育学校については、品川区の取組みが、間違いなく大きく取り入れられていると感じるところであります。\n先ほど説明していただいた中で、今回は施設一体型を義務教育学校とするとお話があったのですけれども、分離型については、検討するか、検討しないかということもあると思うのですが、基本的に分離型を義務教育学校という形でやろうとした場合にどのような問題点が発動するのか。場所が離れているとか、そういうこともありますし、交流するにしても、離れているとやりづらいというのもあるかと思うのですけれども、そこら辺をどのようにお考えになられているか教えてください。"},{"i":114,"speaker":"渋谷指導課長","text":"この辺は大変難しい問題になるのですけれども、例えば一番大きなネックになるのは、義務教育学校になったときに、校長先生を１人にするというところが一番大きなポイントになるのだろうと。施設が離れることによって、校長１人ということで、その管理、マネジメントがうまくできるのかどうかというところがポイントになるのかと思います。"},{"i":115,"speaker":"浅野委員","text":"多分、それが一番大きい課題だとは思うのですけれども、このようになってきた場合に、分離型について同じような教育というのはなかなか難しい部分はあると思うのですが、分離型のよさもこれからつくっていくということでしょうし、今までもやってきたことだと思います。そこら辺を継続しながら、こちらに入ったほうがよかったのではないかとか、こちらのほうがどうなのかという声が上がらない形で、ある意味では平均的というのでしょうか、品川区としての教育の考え方をしっかりと平等に伝わるような形をとっていっていただければと思います。\nあと気になったのが、小学校と中学校の免許状の併用を原則とするというところなのです。今現在、こういう形でそのまま当てはまって、オーケーという割合というのはどのぐらいあるのか。これは、固有教員と都からの教員とは当然違っていると思いますけれども、このような文章が出てきたということになりますと、何らかの形で取組みを進めていくのかと思われるのですけれども、区としての固有教員の考え方と、あとは都から来ていただいた教員の考え方というのでしょうか。そこら辺、何か取組みなどをお持ちであれば教えてください。"},{"i":116,"speaker":"渋谷指導課長","text":"小中一貫教育を進める品川区としては、免許制度については非常に大きな関心を持っているところでございます。\n固有教員につきましては、基本的に小学校、中学校両方の免許を持つようにという働きかけをしていて、初期に採用になった者に一部持っていない者がおりますので、他校種の免許を取る補助制度も用意して、今積極的に促しているところであります。\nまた、東京都に対しては、今後になりますが、義務教育学校設置の暁には、小・中両方の免許を持った人間が取れるような、例えば義務教育学校に対する公募制度の設立等々をぜひ強く求めていきたいと考えているところでございます。"},{"i":117,"speaker":"浅野委員","text":"今、ご答弁いただいたように、区として一番いい方向で教育できるような形をぜひともとっていっていただければと思います。\nその中で、品川区の学校の設置条例というところを見ているのですけれども、小学校と中学校と書かれているのですが、この中で特に左側の小学校のほうで、空欄みたいな形になっているのですけれども、この空欄はそのまま空欄で条例という形になるのですか。それとも詰めるのか。ここら辺はただ単に見ばえをよくするだけでもいいのかとも思うのですけれども、実際に条例となる場合にはどのような形を考えられているか教えてください。"},{"i":118,"speaker":"野呂瀬学務課長","text":"今日お示しした新旧対照表では、対比させる意味で空欄にしておりますけれども、実際に条例になったときには詰めるように考えております。"},{"i":119,"speaker":"大倉委員","text":"浅野委員と少しかぶるのですが、今、当分の間は例外ありということで、小学校、中学校の免許の併有を原則とするというところで、今何人ぐらいいらっしゃるのか教えていただきたい。\n今後、こうやって法律で書かれたということは、進めていかなければいけないというところで、どの程度を目標にして増やしていこうというのを、都のほうにも要望していくというところなのですが、どういう考え方で要望していくのかというところを教えていただきたいと思います。\nあと、こうした法律ができることによって、今まではある程度品川区の考え方でいろいろやってきた中で、何か逆に縛りがかかってきて、やりづらくなってしまうというか、もう少し自由度があったはずなのに、縛られてしまうというところがあるのか。できれば、品川区としていろいろやってきた中で、そういうものがあるのであれば、また国や都など、いろいろなところに要望していかなければいけないと思うので、そういうところがあれば教えていただきたい。"},{"i":120,"speaker":"渋谷指導課長","text":"今の施設一体型小中一貫校の両方の免許取得の割合ですが、大体３割ぐらいということで、３割ぐらいの先生が両方の免許を持っているような状況でございます。\nそれから、方針についてなのですけれども、秋口に新潟県の三条市で小中一貫教育の全国協議会がございまして、その際に前川文部科学審議官、文部科学省の方が今後の免許のことに触れられておりまして、この当面というのは当面だということで、文部科学省としても早急にここ５年、１０年で事態が急速に解決するというものではないと捉えているようでございます。\n私どもとしても、都費の先生については、毎年６分の１ずつ代わっていってしまうという状況があるので、区単独での取組みとなると、積極的にそういった人を集める、また固有教員の取得率を高めていくという方向性が、今とり得るべき最善の方策なのかと考えているところでございます。\nそれから、最後３点目の縛りについてですが、これは先ほどの説明とも重なりますが、文部科学省が今回の法整備をするにあたって、既に全国の各自治体で取り組んでいる小中一貫教育を制限したり、やりにくくしたりするものではないのだという方針で法制化されていますので、今現在、我々が縛りを感じるところはございません。"},{"i":121,"speaker":"大倉委員","text":"わかりました。今後、固有教員等を含め、両方の免許を持って合併していかなければいけないかというところで、わかりました。\nあと、今後のこうした学校教育法の中で義務教育学校というのが認められるようになって、今後、品川区として、当分のところ小中一貫校は６校でというお話が前からある中で、こういうものが設置されて、今後は同じ考えなのかどうか。今後も小中一貫教育に関しては、今の６校で進めていくという考え方に特に変わりはないのかどうか。今後の義務教育学校についての進め方、学校のあり方、進め方に変わりがないかどうか教えていただければ。"},{"i":122,"speaker":"品川庶務課長","text":"義務教育学校６校につきましては、当初小中一貫校６校体制というお話がありましたが、今回、法改正ということもありまして、６校でとめるという考えではなく、やはり今後、少し義務教育学校についてはどのようにやっていくかということで、広げていく考えは、現在のところあるという形で、６校でとどまるという考えではないということでございます。"},{"i":123,"speaker":"大倉委員","text":"今後、分離型なのか、一体型なのかわかりませんが、義務教育学校というものができたことで、品川区の学校のあり方としても、もう少し動きが出てくるような考え方が今出てきたという認識でいいのでしょうか。"},{"i":124,"speaker":"品川庶務課長","text":"直近で何かどうこうするということではありませんが、やはり将来に向けては６校体制でいくということではなく、少し考え方が変わってくるものではないかということでございます。"},{"i":125,"speaker":"大倉委員","text":"いろいろ目指して、学校自体が地域と一緒になってということで進めている中なので、そういった中で考え方が時代の中で少しずつ変わっていく中において、今後そういった検討がされるときは、しっかりと地域の方や、子どもたちが主体ですから、子どもたちのためになるような学校づくりというか、設置についても取り組んでいっていただければと思いますので、よろしくお願いいたします。"},{"i":126,"speaker":"飯沼委員","text":"資料でいただいたイメージ図だと、施設一体型義務教育学校、施設分離型義務教育学校と赤字で書いてあるのですけれども、今までの質疑によると施設分離型の義務教育学校は、当面というか、絶対ではないけれども、今のところは義務教育学校にしていかないのですね。そういうところだと、現状において、義務教育学校とそうでない小学校、中学校が存在するという２種類の種類というか、どう言うのかわかりませんが、できてしまうというところにおいて、小・中義務教育段階から、複数の学校制度が明らかになっていく。今までは特区制度など、いろいろあったのですが、義務教育の段階から明らかに違った校種が同じ区に存在するということにおいて、教育の機会均等が崩されるというか、そういう危惧を持たれても仕方がないと思うのですが、違う校種を置く意味がどこにあるのか。これからどうなるのか微妙だったのですけれども、違う種類を置くことの意味をどこに置いているのか。あと、今後もわかる範囲で明解に言っていただけますか。"},{"i":127,"speaker":"渋谷指導課長","text":"品川区でも、約３割弱のお子さんが何らかの私立、国公立の学校に進むという現状があります。学校選択制をひいている品川区として、品川区の保護者、またお子様にさまざまな選択肢を用意するという１つの方向性としては、区民のニーズに合致したものではないかと考えているところであります。"},{"i":128,"speaker":"飯沼委員","text":"選択肢と言えるのですか。私立と公立を選ぶというのはありますけれども、選択肢というと、違った学校、中身が違う、どういう捉え方をこの２種類に置いているのかというところ。選択してもらう選択肢が多いほうがいいと考えているわけですか。もう一回、そこをお伺いしたいと思います。"},{"i":129,"speaker":"野呂瀬学務課長","text":"当初、私が説明したときに戻りますけれども、今現在小学校が３１校あって、中学校が９校ある。小中一貫校も、日野学園が一番最初にできて１０年たちますけれども、施設一体型の小中一貫校は６校ありました。その６校は、今までは法制化されていなかったから小学校と中学校、それぞれついていましたということだったのですけれども、小中一貫校が今回義務教育学校になったということで、いわゆる実態的には今までと変わらないということを先ほど申し上げたとおりでございます。\nですから、校名が変わるということにつきましても、先ほどもありましたが、例えば豊葉の杜学園というのは、その時点で校名が変わっているのですね。豊葉の杜小学校と豊葉の杜中学校に変わっている。そういうものもありますので、実態としては、今までやっていました施設一体型の小中一貫校が今回法制化に伴って義務教育学校という名前に変わるということを申し上げているところでございます。"},{"i":130,"speaker":"飯沼委員","text":"何かわかりにくい議論になってしまったと思うのですけれども、法律が変わっただけであるとおっしゃるのだったら、何で今までと違って、耳慣れない義務教育学校というものにするのかという話になってしまうのではないでしょうか。これは置いておいて、これは自治体で選べるのですよね。法律ができたから変えなくてはいけないというものではないですね。品川区の意思において変えるのですよね。そこを確認させてください。"},{"i":131,"speaker":"品川庶務課長","text":"それは委員おっしゃるとおりで、法律が変わったということに対して、当然小中一貫教育を進めている品川区として、先行して義務教育学校をやっていこうというスタンスでございます。"},{"i":132,"speaker":"飯沼委員","text":"そこのところに意義があるので、幾つか質問を続けさせていただきます。小中一貫教育、共産党としてはこの間、問題が幾つもあると指摘をさせていただきました。専門家や教職員、現場の方、保護者、地域、児童・生徒の方々の意見も聞いて、検証を行うようにずっと求めてまいりましたけれども、１０年経過をし、来年に教育フォーラムがありますけれども、この間、意見がいろいろ分かれている点や、きちんとした検証結果がいまだ示されていません。まだきちんとした検証結果が出ていない中で、義務教育学校として設置をしていくということ自体が、やはりこの時点で法律ができたから乗っかるというのではなく、ここに理解を得るのは難しいと思います。\n今日の資料で出ていましたけれども、学校教育制度の多様化、弾力化の推進とは一体どういう意味なのかお伺いしたいのが１つです。\nあと、小学校、中学校を廃止し、伝統ある小学校の名前、中学校の名前を廃止すること、学校の名前がなくなるのです。私も日野中学校なのですけれども、こういった大問題を今ある学校の姿だけを知っている人や地域の連合町会や町会長だけにお話しして理解を得たなんて、とんでもないことであると思います。私はこの間、地域と学校のさまざまな連携が大事と言われているし、ますます地域での学校の存在が大きくなっているのに、この大問題を品川区教育委員会が一部の人だけに伝えて、十分理解を得ていますと言ったもので、勝手にできるものではないと思っています。これは大問題という捉え方をしていただきたいのが１点です。\nあと、小中一貫校をつくっていく段階で、たくさんの声が上がったのです。当時、品川区教育委員会は何と言って一貫校に移行していくことを説明していたのか。特に校名について、どのような説明をしていたのか、改めてお伺いしたいと思います。"},{"i":133,"speaker":"品川庶務課長","text":"いろいろご質問がありましたが、基本的に今回の件に関しましては、学校教育法の改正によって義務教育学校を設置していくというものでございますので、今までの一貫校の検証がどうだという話は、少し議論がずれているのではないかと考えてございます。\nそれから、周知の件に関しましては、先ほども答弁しておりますとおり、連合町会長、学校説明においても当然説明をしてございます。その中で、小学校、中学校の旧学校名についてはなくなるというお話も説明しております。\nそれから、ＰＴＡのほうにも小学校ＰＴＡ連合会、中学校ＰＴＡ連合会にも集まっていただきまして、この点についても説明してございます。周知についても、十分説明をしているということでございます。"},{"i":134,"speaker":"飯沼委員","text":"検証と関係ないというか、新しい試みをして、検証すると言いながら、委員会の設置をしているわけですよね。検証をしていますよね。検証結果を一緒に示すから、今やっている区教育委員会のやり方を理解してもらうのだと思います。検証は別です。「ずれています」と言われたら、何を見て支持をしたり、支持をしなかったり、意見を言うのか、わからなくなってしまうのではないか。今のやりとりはおかしいです。全然答えになっていない。\nあと、条例審査と言っていますけれども、中身の問題がわからなくて、明らかにしないでしていくなんてとんでもないことであると思います。庶務課長、今、周知は十分だと言っていますけれども、どれくらいの方とこの間、どの期間に、いつぐらいの間にどのくらいの方々にこれをお伝えしたのか。口頭なのか、文書があるのだったら、文書を示していただきたいと思いますが、いかがでしょうか。"},{"i":135,"speaker":"品川庶務課長","text":"再度説明申し上げますが、法改正による義務教育学校の設置でございます。先ほども指導課長から答弁がありましたように、検証についてはさまざまな課題がまだ残っているということで、答弁があったと思います。\nそれから、周知の点につきましては、いつというところでございますが、義務教育学校の具体的な説明会は９月下旬に行われました。その後、周知を開始しておりますので、９月下旬から１０月上旬につきまして周知を行ってございます。周知の相手先については、先ほどから何度も答弁しているとおりでございます。"},{"i":136,"speaker":"飯沼委員","text":"何度も聞くのは、きちんと答えてくれないからです。９月の下旬から１０月の上旬まで周知、相手は先ほど述べたとおりです。私は何人ぐらいの人にお伝えしたのですか、文書なのですか、口頭なのですかと聞いていますので、きちんと答えてください。"},{"i":137,"speaker":"品川庶務課長","text":"人数につきましては、学校説明会に来られている方の人数になりますので、６校で大体２日間ぐらい学校説明会が行われています。確かに１人１人、人数を数えているという状況ではございませんので、ある程度の説明で人数の規模はご理解していただけるかと思います。\nそれから、その際に書面を出しまして説明を行っているという状況でございます。"},{"i":138,"speaker":"塚本委員長","text":"そろそろまとめていただきたいと思います。"},{"i":139,"speaker":"飯沼委員","text":"同じ質問ばかり繰り返すつもりはないのですが、もう一回、学校説明会というのは、対象はどういう方なのでしょうか。文書を出したのだったら、ぜひその文書を後で見せていただきたいと思います。\nあと、小中一貫校が始まる当時、地域の住民の方に何と言っていたのか、もう一回お尋ねします。私は、この間、統廃合はしないと言ってきたけれども、結果的において小中一貫校が行われていく中で、本当に統廃合がどんどん進んできたと思います。この間、反対運動が幾つもあったので、ぜひ後から議員になった方も知ってほしいし、忘れないでいただきたいと思います。小中一貫教育は、区民の願いや議会からの要望ではありませんでした。文部科学省の肝入りで、当時の若月教育長がＰＴＡや教職員、議員からの意見を無視して、「無視して」とあえて言いますが、導入して強行した経過があります。\n１校目の日野学園、日野中学校のＰＴＡから日野中学校を移転しないでくださいと教育委員会に３,５００筆の署名が提出され、議会にも小中一貫教育計画の中止を求める請願が出されていました。ぜひ聞いてください。\n２校目、伊藤学園も原小学校のＰＴＡが父母のアンケートを行って要望書を提出しました。\n荏原平塚学園、二中と平塚中の突然の合併に反対が起こりました。そして、中学校を合併させた後に、平塚小学校は３校の統合だったのですが、ＰＴＡから懸念や不安の声が陳情されました。\n豊葉の杜学園は、施設や運動場の狭さなどについて、たくさんの不安の声があり、議会にもたびたび請願が出されました。\n品川区の小中一貫校は区民の願いで設置されたものではなく、教育改革と称して、結果的には学校の統廃合を進めてきたことを、いよいよ現実的に名前がなくなっていく、書きかえられていくということで、否定できない状況になっていると思います。義務教育学校６校設置ということで、小学校をこの間ずっと見ていると９校、中学校も９校、あわせて１８校の小学校、中学校の名前が、この品川区から消えていくわけなのです。このことを法律が変わって義務教育学校に移るだけですと、本当に法律的には１枚の紙で終わってしまうのかもしれませんけれども、この間の流れ、廃校の流れ、学校の統廃合のほか何物でもないと思っています。統廃合と出したら、絶対反対の動きがいっぱい起こってしまうので、子どもたちの教育改革ということで進められてきたわけなのですけれども、私はこの経過から見て、現実的には、今回の名前をなくす、廃校ということです。本当に許されないことであると思いますが、この中身は、私はあまりにも強引ではないか、ひどい、理解を得られないと思っているので、この点について、何でしょうか。"},{"i":140,"speaker":"塚本委員長","text":"質問してください。"},{"i":141,"speaker":"飯沼委員","text":"質問しています。"},{"i":142,"speaker":"塚本委員長","text":"ご意見はもう十分伺いましたので、質問をしていただいて。"},{"i":143,"speaker":"飯沼委員","text":"思いも言わないと、思いのほうが大事ですので。\nなので、当時何と言っていたのかという質問を先ほどしましたけれども、このやり方、「十分しています」と、本当に区民の方の理解を得られていると思うのですか。私はとてもではないけれども、理解できないのです。私だけではないと思いますが、いかがでしょうか。"},{"i":144,"speaker":"品川庶務課長","text":"いろいろお話をいただきまして、再度繰り返しのところになって大変申しわけないのですが、法改正による義務教育学校設置ということで、周知につきましても先ほど答弁したとおり、９月下旬から１０月上旬まで説明会等を行っております。その中で、特に校名がなくなるという点について反対の声というのも特段聞いてはございませんし、いろいろ区民の方々の思いはあると思います。逆に、今はこれだけ小中一貫校で名前が住民に聞き慣れているという状況の中で、かえって校名を変えるということに対しても、今度はどうかという意見も出てくるかと思います。校名については、いろいろご意見はあると思いますが、今現在、慣れ親しんでいる名前で学校名はいくということで判断をしているところでございます。"},{"i":145,"speaker":"飯沼委員","text":"あと、施設の基準が具体的にきちんと出ていない話も聞いているのですけれども、義務教育学校の前期だと今までの小学校、後期だと中学校のそれぞれを積み上げていくということなのですか。その辺の義務教育学校の施設設備の基準、先ほど校長先生が１人になるという話は聞いたのですが、教職員の配置基準など、明確に出ているのでしょうか。今の基準をしっかり守るというのと、私としては、大規模化の中で手厚くしていただきたいと思うのですが、その辺の基準がどうなっているのかと、区が進めている上でどういう中身でいくのかというところを教えてください。"},{"i":146,"speaker":"品川庶務課長","text":"基準につきましては、現行の小中一貫校がやっている中で進めていくということになりまして、細かい基準については、まだ現在のところ出されているような状況ではございません。先ほど委員がおっしゃったとおり、説明の中でもありましたとおり、校長先生１人、副校長先生３人という体制。これについては具体的に出ておりますが、それ以外についてはまだまだ基準というのは、現在のところ特段出されている状況ではございません。"},{"i":147,"speaker":"飯沼委員","text":"基準はとても大事であると思うのです。今までは、従来のところで特例的にやっていたけれども、いよいよ一体化のところで義務教育学校というのであれば、やってきた問題点をしっかり出して、改善していく中身でどんどん提案していくべきだと思うのです。\n私たち共産党としては、今回の法整備にあたってぜひ主張してほしいのは、品川区の６校の小中一貫校はどこもほとんど大規模ですね。６校中４校が１,０００名を超えていたり、若干少ないくらい、九百何十人といったところでは、大規模な学校である。大規模化の問題点をしっかり捉えていただきたいと思うのですが、このところ行事にしても、例えば伊藤学園は校庭が狭いので、運動会をするときに父母が校庭に入れなくて、建物のベランダから子どもたちを見るとか、広くないところにたくさんの子どもがいるので、出る競技もすごく限られていて、いろいろ制約がある。特に行事は大規模で人数が多いと待つことが多かったり、控えるところが多かったりということで、いろいろ行事の制約が多いのではないかと思いますけれども、そういったところで子どもたちの成長、運動場は身体の発達にいろいろ影響が出てくるのではないかと思っているのです。この大規模化に対して、特に配慮を考えているところがあるのでしょうか。"},{"i":148,"speaker":"品川庶務課長","text":"施設の面につきましては、基本的には一貫校につきましては小学校の基準、中学校の基準等はありますので、それに合わせた形で設置をしているところでございます。\nそれから、グラウンドが狭いとか、そういう問題はいろいろあると思います。これは、当然用地の問題になってまいりますので、なかなか広い土地にすぐ学校をつくるという状況は品川区の中では非常に難しいところではないかと思います。そういう中でも、学校の設置基準にのっとった形でしっかりと学校建設はしておりますので、よろしくお願いいたします。"},{"i":149,"speaker":"飯沼委員","text":"しっかりやっていますということなのですけれども、実際的に学校によってすごく格差があります。１つには校庭のところなのですけれども、子どもが体を動かして、体力的にも伸び伸びと育ってほしいというところで、校庭の格差と言ってしまっていいくらい広さにすごく違いがあると思うのです。その点、この間、国会のほうに行っていろいろ聞いてきたのですが、小学校と中学校はあるのだけれども、すごくぐずぐずというか、これから決まるのだけれども、共有もあり得るという、兼ねてしまってもいいようなところもあるみたいな話を聞いてきました。このままいくと、それこそ統廃合というか、寄せて集めて、大勢の子どもを入れてほかをあけていくみたいなところができてしまうので、ぜひ施設基準というのは、まだ国でしっかり政省令で決まっていないというところなので、実際に大規模でやっているのですから、そこのところの基準、今の品川区のままでクリアしてもらおうと思うのではなくて、よりよい基準を出していただかなくてはいけないと思っています。\nあと、大規模のところにあまり問題意識を持っていらっしゃらないようなのですけれども、大規模化の問題は、これからの学校を考えていくときに、私はもっと子どもたち一人ひとりに目が届く学校にしていくためには……。\n〔「条例審査だよ」と呼ぶ者あり〕"},{"i":150,"speaker":"飯沼委員","text":"何ですか。条例審査だからこそ、中身を言っているのではないですか。\n〔「それは内容ではないでしょう」と呼ぶ者あり〕"},{"i":151,"speaker":"飯沼委員","text":"内容です。\n〔「違う、条例審査なのだ」と呼ぶ者あり〕"},{"i":152,"speaker":"塚本委員長","text":"これは、あくまでも義務教育学校の中身は、基本的には今回の法律では変わらない。今まで品川区がやってきた小中一貫教育は変わらないという前提がまず１つあって、そこに法律としての整合性を整えるという条例ですので、そこを踏まえた上で、学校教育とは何ぞやとか、いろいろなことをやってしまうと、とても時間も足りませんので、その点配慮いただいて、まとめていただきたいと思います。"},{"i":153,"speaker":"飯沼委員","text":"小中一貫校のことをお互いに議論できる時間はあまりないですよね。この間、所管事務調査でも少しありましたけれども。"},{"i":154,"speaker":"塚本委員長","text":"その辺は、もちろん議論したい、いろいろな場で議論したいという気持ちはわかりますが、時間も限られておりますので、今日の委員会の審査をまとめていただくようにお願いを申し上げます。"},{"i":155,"speaker":"飯沼委員","text":"わかりますけれども、義務教育学校にしていくときだからこそ、大規模化や中身自体を考えていって、よりよいものにしようという姿勢がない限り、はい、そうですか、法律が変わったので、品川区のことを後押ししてくれるからと、それで変えていくという立場にはとても立てないのです。私は、ぜひ大規模化の問題点がいっぱい出ています。校庭や行事のところだけではありません。やはりよりよい規模を、教育委員会としてはぜひ考えていっていただきたいという思いがあるので、今日ここで述べさせていただきましたけれども、教職員の配置基準、施設と設備、学校の規模、学級数をどう捉えているのですか。標準というか、普通の学校の規模と義務教育学校の学級の規模をどう考えているのですか。こういう中身をわからないで賛成するのですか。おかしいではないですか。"},{"i":156,"speaker":"塚本委員長","text":"質問を続けてください。"},{"i":157,"speaker":"飯沼委員","text":"しました。"},{"i":158,"speaker":"塚本委員長","text":"では、答弁お願いします。"},{"i":159,"speaker":"品川庶務課長","text":"施設に関しましては、これも繰り返しの答弁になりますが、小学校の基準、中学校の基準に合わせた形で義務教育学校もやっていくことかと考えております。\nただ、特段国や都から新たな基準が出れば、それに合わせてやっていきたいと考えております。\nそれから、クラス数については、この法律の中で何クラスにするとか、何クラス以上つくるとか、そういう基準が特にございませんので、その地域の実情に応じた形、それから、仮にですけれども、校舎を新たに建てるという形については、その広さ等も考えながらクラス数の設定をしていくのかと思いますし、就学人口等によってもクラス数というのは違ってくると思いますので、特段そういった何クラスにしていくということでお答えできる部分についてはないのかと思っております。"},{"i":160,"speaker":"飯沼委員","text":"最後になります。学級数の規模は、国の段階で多分これから出てくると思うのです。今議論されているところであると思います。\nあと、文部科学省も過大規模校では生徒の個性や行動を把握しづらく、問題行動が発生しやすくなることも考えられると、やはり問題点を指摘しているのです。そういった意味で、ぜひ地方から声をどんどん上げていって、子どもたちのための基準が守られるような状況に力を尽くしていただかなければ困ると思いますので、よろしくお願いいたします。"},{"i":161,"speaker":"高橋（し）委員","text":"幾つかお尋ねするのですが、まずこれは質問というよりも、副校長先生が３人になったということで、これはおそらく品川区で現状１０年やってきて、これだけの先生がいらっしゃらないとなかなか厳しいというのを文部科学省に主張していただいて、通ったのではないかと思っています。やはりこれぐらいの形、もしかしたらもう一人いらっしゃってもいいような状況だと思うので、これはこうなったことがまずは１つ、今後の運営で大きな意味を持つのではないかと思っています。\n先ほどの前期課程と後期課程のことなのですが、６年と３年なのですが、これと「４－３－２」というカリキュラムで、はっきりと前期課程と後期課程で「６－３」になったわけです。「４－３－２」とカリキュラム上はなっているのですが、現在「４－３－２」についてはなかなか保護者の方にもご理解いただけていない部分があって、よりわかりにくくなってしまう可能性があるので、その辺のご説明といいますか、明らかに「６－３」となってしまったわけで、それを「５－４」に、前期５年、後期４年にできないので、その「４－３－２」のカリキュラムの周知について、どのようにお考えなのかというところ。\nあとは、免許の件で、両方持っている方と、現在はそうでない方といろいろ制限があります。それは、今回の改正でも残って、先ほども少しありましたけれども、逆にそれを厳しく制限するという部分がなければ、ある程度現在のやり方でいけるのでしょうけれども、その辺の制限というのが今と同じように先生方はお仕事ができるのかというところです。\nそれから、特別支援学級は、学級数や先生の配置など、そのまま現状と同じようにいくのでしょうか。その点について、法律を、特別支援学級のほうを見ていないのでわからないのですけれども、すみません。\nその３点。"},{"i":162,"speaker":"渋谷指導課長","text":"「４－３－２」がわかりにくいのではないかという２点目のご指摘については、現在は小学校６年、中学校３年という「６－３制」の枠組みの中で小中一貫教育は「４－３－２」の枠組みをやっていますので、基本的な部分ではそこも変わらない。義務教育学校になっても、６年の課程の修了、後期の課程の修了ということでありますので、小学校、中学校という名前が前期課程、後期課程と変わるだけで、現行とは変わらない。ただ、「４－３－２」については、保護者アンケート等をやっても、なかなかご理解が進んでいない現状がありますので、この部分については小中一貫教育推進委員会の中でも話題になっておりまして、今後、学習指導要領の改訂にあわせて品川区の小中一貫教育要領を見直す際には、そういった部分もあわせて検討していきたいと考えているところでございます。\nそれから、免許についても、現行取り組めていること、例えば中学校の体育の先生は小学校の体育の授業を教えることができる等々ありますので、そういった枠内での活動は今までと何ら変わらないということで理解しているところでございます。\n特別支援教育につきましては、現行のものが基本的には踏襲されていくという理解でおります。"},{"i":163,"speaker":"高橋（し）委員","text":"今ちょうどお話が出たのですが、小中一貫教育推進委員会の第２回で、平成３１年から品川区義務教育新体制の提案とあって、平成３１年というのはコミュニティ・スクールも全校に配置され、学習指導要領も平成３１年度は小学校が入るわけです。それで、お話があったように、品川区の教育課程を新たに決めていくというところなのですが、そこまでにあと何年かあるのですが、その中で平成３１年からの体制のことを考えていかれると思うのです。その辺に向けて、先ほどいろいろ議論がありましたけれども、大きな枠の中でといいますか、考え方というか、平成３１年からについての現状をどういうお考えで進めようとしているのかというところをお尋ねしたい。"},{"i":164,"speaker":"渋谷指導課長","text":"今、まさに小中一貫教育推進委員会等々で議論しているところでありますが、目指すところは品川区としては９年間の義務教育にしっかりと責任を持っていこうというところでございます。９年間、しっかり子どもたちが力をつけ、また人間性をしっかりと育成できるような仕組みを１つ考えていくために、義務教育学校の制度、あるいはまたこの後導入していく品川版のコミュニティ・スクール等々の仕組みを十二分に活用しながら、地域の子どもたちをしっかり育てていくような教育を執行していきたいと考えているところでございます。"},{"i":165,"speaker":"高橋（し）委員","text":"そうすると、平成３１年からの体制づくりにとって重要な検討、この推進委員会もそうだと思いますので、議会も含めて議論をする機会をつくっていただければと思います。\nもう一つは、先ほどの小中一貫の分離型なのですけれども、結局分離型だと義務教育学校というのはつくりにくいというか、先ほど言った校長先生の問題などもあります。そうすると、今後、分離型小中一貫校、非常に難しい事情の中で各校協力して、実質的な小中一貫校的なことをやられているところが多いと思うのですけれども、そこのところが逆にこうなった結果、分離型が少し義務教育学校に移りにくくなったわけです。事実上、分離型も存在しますけれども、そこのところで分離型小中一貫校の位置づけというのを、先ほどの平成３１年からのところにつながるのかもしれませんけれども、どのようにお考えでしょうか。"},{"i":166,"speaker":"渋谷指導課長","text":"実際、品川区の状況としては、小学校と中学校の学区域がすっきりとしていない部分があって、１つの小学校が２つの中学校に行くような状況も今現在あります。そういった中で、具体的な連携のとり方に少し工夫が必要だと思っているところもあります。\n１つ、コミュニティ・スクール等々を考えながら、学校の教育活動の中での連携、また教育活動外の放課後や土曜日も含めて、総合的に子どもたちを９年間見ていく仕組みとして、品川版のコミュニティ・スクールということを考えております。１つのキーワードは、やはり地域とともにある学校ということで、中学校区という大きなまとまりで義務教育というものの９年間を考えていくような仕組みができるといいのかなと考えて、さまざま今検討しているところでございます。"},{"i":167,"speaker":"高橋（し）委員","text":"まとめます。どうもありがとうございます。\n分離型は非常に課題が多いのですが、今までばらばらだった小学校と中学校が結びついて、いい効果もたくさん出ていますので、ぜひよいほうに向くようにお願いします。\n最後、これは質問というよりも、一般質問でもお話ししたのですが、１０月下旬あたりにいろいろ地域にも説明され、在校生や新入生にも説明されたわけですね。その後、３回目の定例会があり、さらに閉会中もあったのですが、ほかの事項では結構進捗状況みたいなことをお話ししていただいたのですが、時間がなかったので本会議でお話しできなかったのです。途中経過みたいなもので報告をしていただければ、その時点でもう少しお話ができて、より今回につながったのではないかと思っております。本会議の質問ですので、繰り返しになってはいけませんので、そこのところを感想というか、お話しして、そこまで。"},{"i":168,"speaker":"伊藤副委員長","text":"まず、義務教育学校の確認ですけれども、これは品川区をはじめとした小中一貫教育の全国での実践が、いろいろなところから文部科学省に届いて評価をいただいた。それが現場のさまざまなマイナス面やプラス面もあって、法的に整備していただいたということがあって、今回義務教育学校ということで出てきたと思うのだけれども、その解釈でいいのかどうかということが１つ。\nそれから、改めて義務教育学校になった後、では品川区がどういう教育を展開して、子どもたちのためにすばらしい素質のあるものを展開していくのかということのほうがより重要だと思うのだけれども、その２つをまずお答えください。"},{"i":169,"speaker":"渋谷指導課長","text":"今、委員ご指摘のとおり、義務教育学校の創設につきましては、地域の実情や児童・生徒の実態、さまざまな要素を総合的に勘案して設置者が主体的に判断できるように、従来の小学校・中学校に加えて、義務教育を行う学校の設置の制度上の選択肢を増やしてくださったということで、品川区はもちろんですけれども、品川区以外の僻地であったり、島嶼にある１小１中のような学校も、より義務教育の質の向上を目指せるということで、選択肢を増やしたという意味づけでございます。ご指摘のとおり、こういった取組みは、我々の教育を後押ししているものであるし、義務教育全体の質の向上を目指していくものであろうと考えているものでございます。\n品川区としても、義務教育の学校の取組み、導入があって、選択肢が増えたことによりまして、さらに品川区全体の義務教育の質の向上に強い決意を持って取り組んでいきたいと思っているところでございます。"},{"i":170,"speaker":"伊藤副委員長","text":"法改正ですから、これは品川区のみならず、全国の話であるから、おそらく全国の自治体の中で、形はどうあれ一貫校を展開してきた。それである程度評価が来た。でも、法的な位置づけがなかなかないということがあって、文部科学省としてはおそらくさまざまな議論を経た上で、法律ですから、そういうことを当然文部科学省としては調査してきたと思うので、ほかの意見にあったように、一方的に一貫がだめだということではなくて、さらに前に進めていく意味の教育の価値は相当あったと思うのだけれども、その解釈を確認でもう一度だけ教えてください。"},{"i":171,"speaker":"渋谷指導課長","text":"今回の制度化は、小中一貫教育を通じた学校の努力による学力水準の向上や、また学校の団体間の接続に関する優れた取組みの普及による公教育全体の水準向上に資するというのが、国の大きな考え方だと思っているところでございます。私どもも、ぜひまた品川区全体の教育、９年間の義務教育というものをしっかりと見据えて取り組んでいきたいと思っております。"},{"i":172,"speaker":"伊藤副委員長","text":"あと、先ほどの質疑の中で、議会が小中一貫教育に反対するような意見があったのだけれども、これはあえて言っておくのだけれども、私も長く議員をやっているから、確かに自民党は当初懐疑的でありました。だけど、さまざまなことをお伺いさせていただく中で、品川区の姿勢や品川区の教育への取組み、それから実際の教育現場をたくさん見てきた中で、これは非常に功績があるということで、方向性を変えてきました。それに伴って、ほかの会派もさまざまな議論を経た上なのだけれども、議会としても、それはある程度、してきたことは事実です。複数回、私も何回か記憶していないのだけれども、おそらく反対の請願、陳情が出てきたのです。だけど、議会として一度もそれを採択したことはないのです。\n確かに意見だから、それはいろいろな意見で当然だと思うけれども、一方的に反対意見だということではなくて、議会としては必要なことも踏まえた上で、しっかり議論をしてきて、皆様の前にという思いがあるので、そのことについて、誰に聞けばいい。教育次長でいいですかね。答弁いただければと思います。"},{"i":173,"speaker":"本城教育次長","text":"今、お話しいただきましたように、法改正で今度新たに制度化されたことは、今まで私どもが取り組んできた、議会からもご支援いただきながら取り組んできたところに、安定的な仕組みとしての基盤を与えてもらったのだと思っております。そういう意味で、さらに先ほども一部答弁させていただきましたが、これを１つの契機として、日々、教育の改善、向上に努めていきたいと考えているところでございます。"},{"i":174,"speaker":"伊藤副委員長","text":"まとめますけれども、要は議会はさまざまな議論をする場であるから、賛成、反対で当然なのだけれども、私たちとしては、特に小中一貫教育については、今まで何十回も委員会等で議論してきました。それから、請願も出てきたし、陳情も出てきたし、その場、その場できちんと議会として議論をして答えを出してきたわけであるから、ほかの委員の意見にあったように決して反対ということではなく、いいものはいい、悪いものは悪いと評価しながらやってきたわけでありますから、そういうことを踏まえた上で品川区の教育施策を前進していただきますようお願いしておきます。よろしくお願いします。"},{"i":175,"speaker":"塚本委員長","text":"では、ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、本件に対する各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いします。"},{"i":176,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":177,"speaker":"浅野委員","text":"賛成します。"},{"i":178,"speaker":"飯沼委員","text":"意見を添えて反対いたします。\n小中一貫校ですが、１０年を経過しましたが、はっきりしているのは統廃合が進んだこと、この間、専門家や教職員の方々、保護者、地域からも教育的効果に疑問が出されています。検証を求めていますが、いまだ示されないままでありますので、一方的に義務教育学校への移行は認められないということで反対いたします。"},{"i":179,"speaker":"大倉委員","text":"賛成します。"},{"i":180,"speaker":"高橋（し）委員","text":"賛成します。"},{"i":181,"speaker":"塚本委員長","text":"それでは、これより、第９０号議案、品川区立学校設置条例の一部を改正する条例について、採決いたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":182,"speaker":"塚本委員長","text":"賛成多数でございます。\nよって、本案は、原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(4) 第９１号議案 学校教育法等の一部を改正する法律の施行に伴う関係条例の整備に関する条例"},{"i":183,"speaker":"塚本委員長","text":"ただいま、第９０号議案、品川区立学校設置条例の一部を改正する条例が可決されましたので、次に、(4)第９１号議案、学校教育法等の一部を改正する法律の施行に伴う関係条例の整備に関する条例を議題に供します。\nそれでは、本件につきまして、理事者より説明願います。"},{"i":184,"speaker":"品川庶務課長","text":"それでは、私から、第９１号議案、学校教育法等の一部を改正する法律の施行に伴う関係条例の整備に関する条例についてご説明いたします。\nすみません。一部資料訂正がございます。１番、改正理由の４行目になります。かぎ括弧で「義務校育学校」となっておりますが、「義務教育学校」と直しを入れていただきたいと思います。\nそれでは、説明を続けさせていただきます。第９１号議案で審議する２番にあります関係条例１３本について、学校教育法の改正に伴う件でございますので、こちらにつきましては通常文教委員会以外の常任委員会で審議する条例もございますが、文教委員会で一括で審議をさせていただきたいと思ってございます。\nそれでは、次ページをご覧いただきたいと思います。それぞれ１３の条例の新旧対照表がございます。\nまず、職員の旅費に関する条例でございます。こちらにつきましては、第１条３項におきまして、教員の旅費に関して、別に条例で定めることと規定されておりますが、教員の定義として、「区立小学校、中学校」という記載がある後に、「義務教育学校」を加えるものでございます。\n続きまして、２番目でございます。品川区奨学金運営委員会条例でございます。こちらにつきましては、第３条におきまして、運営委員会を組織する構成員について規定されておりますが、「区立中学校長」の後ろに、「区立義務教育学校長」を加えるということになってございます。\nページをおめくりいただきまして、続いて品川区女性福祉資金貸付条例でございます。こちらにおきましては、第４条２項におきまして、就学支度資金とは、各種施設に入学する際に必要な資金であると規定をされております。その対象施設としまして、「小学校」のところに「義務教育学校の前期課程」、「中学校」のところに「義務教育学校の後期課程」ということで加えるものでございます。\n続きまして、品川区立学校施設使用条例でございます。こちらにつきましては、グラウンド等の開放を定めている条例でございます。その中で、別表のところをご覧いただきますと、別表の中に日野学園、品川学園ということで記載がございます。日野学園につきましては、体育館を開放するときに、全面を３分割にして開放しているという記載がございます。それから、品川学園につきましても、グラウンドを４分割にして貸出しをしているという記載がございます。今回、義務教育学校になるということで、校名を「品川区立第二日野小学校・品川区立日野中学校」と記載のあるところを、「品川区立日野学園」と記載をしております。それから、「品川区立品川小学校・品川区立城南中学校」と記載してあるところにつきましても、「品川区立品川学園」と記載をしてございます。\n続きまして、品川区立品川歴史館条例でございます。こちらも別表１について、第５条にかかる歴史館の観覧料について定めているところがございます。備考欄の児童・生徒を定義する箇所について、「小学校」の後に「義務教育学校の前期課程」、「中学校」の後に「義務教育学校の後期課程」を加えているというものでございます。\n続きまして、職員の勤務時間、休日、休暇等に関する条例でございます。こちらにつきましては、第１条２項で職員の勤務時間、休日、休暇等に関しては、別に条例で定めることと定義してございます。職員の定義としまして、「小学校、中学校」と記載のあるところに「義務教育学校」を加えるものでございます。\nそれから、その下です。続きまして、学校教育職員の勤務時間、休日、休暇等に関する条例、次のページにいきまして、学校教育職員の給与等に関する特別措置に関する条例、さらに学校教育職員の旅費に関する条例の３つにつきましては、学校教育職員として小学校、中学校の副校長、教諭等を定義している部分がございます。「小学校、中学校」と定義してある部分の後に「義務教育学校」を加えるというものでございます。\n続きまして、品川区災害対策基本条例でございます。こちらにつきましては、第３１条のところでございますが、避難所の開設場所として「小学校、中学校」と規定してございます。この中に、新たに「義務教育学校」を加えるというものでございます。\nページをおめくりいただきまして、続いてが品川区放課後児童健全育成事業の設備および運営の基準に関する条例でございます。こちらにつきまして、まず第６条です。事業の対象となる児童に「義務教育学校の前期課程に就学する児童」を加えるようになってございます。「小学校に就学している児童」とあるところに、「義務教育学校の前期課程」を加えるものでございます。\n続きまして、第１９条です。第１９条につきましては、放課後児童健全育成事業の開所時間および日数について規定をされているところです。こちらにつきましては、小学校の授業の終了の時刻を考慮すると規定が書いてございます。その後に「義務教育学校の前期課程」を加えるものでございます。\nそれから、第２１条、こちらも放課後児童健全育成事業者が利用者支援を行うに当たり、密接に連携する関係機関という定義のところの「小学校」の後に「義務教育学校」を加えるものでございます。\n続きまして、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例をご覧いただきたいと思います。第３条３項、第１１条につきましては、特定教育・保育施設等の運営に関し、密接な連携に努めなければならない施設という定義の中に「小学校」とありますが、ここに新たに「義務教育学校」を加えるものでございます。第１１条についても同様の内容となります。\nそれから、第２７条におきましては、特定教育・保育施設が、支給認定子どもに関する情報を提供する際に、あらかじめ親の同意を得なければならないと規定されておりますが、この情報提供先に「小学校」があるのですが、この後に「義務教育学校」を加えるというものでございます。\nページをおめくりいただきまして、最後です。品川区私立認定子ども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例でございます。こちらにつきましては、第３条に私立認定子ども園等の利用者負担額について、生計を一にする世帯に、小学校第３学年までに在学している児童がいる場合の減免について規定されてございます。ここの「小学校」の部分に「義務教育学校の前期課程の第３学年までに在学している児童」を加えていくものでございます。"},{"i":185,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。よろしいでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":186,"speaker":"塚本委員長","text":"ご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来から。"},{"i":187,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":188,"speaker":"浅野委員","text":"賛成します。"},{"i":189,"speaker":"飯沼委員","text":"文言の整理なのですけれども、今回、義務教育学校設置に反対をしていますので、反対いたします。"},{"i":190,"speaker":"大倉委員","text":"賛成です。"},{"i":191,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":192,"speaker":"塚本委員長","text":"それでは、これより、第９１号議案、学校教育法等の一部を改正する法律の施行に伴う関係条例の整備に関する条例について、採決いたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":193,"speaker":"塚本委員長","text":"賛成多数でございます。\nよって、本案は、原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(2) 第８９号議案 品川区保育の実施等に関する条例の一部を改正する条例\n(6) 第９３号議案 品川区立幼稚園条例の一部を改正する条例"},{"i":194,"speaker":"塚本委員長","text":"次に、(2)第８９号議案、品川区保育の実施等に関する条例の一部を改正する条例、および(6)第９３号議案、品川区立幼稚園条例の一部を改正する条例を一括して議題に供します。\n本件２議案につきましては、関連する内容のため、一括して説明、質疑を行い、その後、議案ごとに採決を行いたいと思いますので、よろしくお願いいたします。\n本件につきまして、理事者より一括してご説明願います。"},{"i":195,"speaker":"竹田保育課長","text":"それでは、私から第８９号議案、品川区保育の実施等に関する条例の一部を改正する条例についてご説明いたします。\n１、改正理由は、第９０号議案において説明がありましたとおり、学校教育法等の一部を改正する法律が公布され、小学校から中学校までの義務教育を一貫して行う義務教育学校が新たな学校種として規定されました。区では、既存の施設一体型小中一貫校６校を義務教育学校として位置づけることとしました。このことから、品川区保育の実施等に関する条例について、規定整備を行います。\nあわせて、その他の規定整備を行うことといたします。\n２、改正内容ですが、義務教育学校の設置に伴う規定整備の改正概要は、第５条２項に多子減免制度の対象児童について規定しておりますが、「小学校」の後に、「もしくは義務教育学校の」を追加し、「小学校もしくは義務教育学校の第１学年から第３学年までに在籍している児童」といたします。\nまた、別表第３の規定中に「小学校」の文言の次に、「または義務教育学校の」を追加し、「小学校または義務教育学校の」といたします。\nまた、区立認定子ども園の保育料改正に伴う規定整備の概要は、入園料に関する条文を削除いたします。\n３、新旧対照表は別紙のとおりです。\n４、施行期日は、平成２８年４月１日から施行いたします。ただし、既に第３回定例会におきまして平成２８年４月１日から施行する一部改正条例をご議決いただいておりまして、今回さらにその一部を改正する義務教育学校の設置に伴う規定整備の規定については、公布の日から施行することといたします。\n次に、第９３号議案、品川区立幼稚園条例の一部を改正する条例についてご説明いたします。\n１、改正理由ですが、義務教育学校に関する部分は、第８９号議案と同様でございます。このことから、区立幼稚園条例について規定整備を行います。\nあわせて、その他の規定整備を行うことといたします。\n２、改正内容ですが、義務教育学校の設置に伴う規定整備は、第４条２項について、第８９号議案と同じ改正を行うものでございます。\n規定の整備ですが、改正概要は保育料の減免について、免除規定のほかに減額規定を追加いたします。\n地方税法の改正に伴い、該当条文を変更いたします。\n新旧対照表は別紙のとおりでございます。\n施行期日につきましては、平成２８年４月１日から施行いたします。ただし、以下の規定については、公布の日から施行いたします。\n別表第２備考第１号の規定、これは先ほどご説明いたしましたが、地方税法改正に伴う該当条文を変更するものでございます。\n2)既に第２回定例会におきまして、平成２８年４月１日から施行する一部改正条例をご議決いただいておりまして、今回さらにその一部を改正する義務教育学校の設置に伴う規定整備の規定については、公布の日から施行いたします。"},{"i":196,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":197,"speaker":"飯沼委員","text":"第９３号議案の新旧対照表のところで、２／５ページのところの第６条なのですけれども、保育料の減免の項目です。赤字で「これを減額し、または免除することができる」と、「減額し」が新しく入っているのですけれども、この保育料の減免規定に減額を入れるとどういうふうになるのか。どういうふうにこれを読んだらいいのか教えてほしいのと、「委員会が特に必要と認めたときは」というのは、どういう例があるのか、具体的に教えていただきたいと思います。"},{"i":198,"speaker":"竹田保育課長","text":"新旧対象表をご覧いただくと、旧の部分については、「保育料の減免」というタイトルでございますが、「免除することができる」という文面になっております。ですが、従来から免除と一部免除という形で解釈しておりましたので、これをより適正な表現にすべく、「減額し、または免除することができる」ということで、より表現を適切な表現に改めたものでございます。\n委員会が特に必要と認めたときというご質問ですが、今後、発生するものとしましては、みなし寡婦の減免等を考えているところでございます。"},{"i":199,"speaker":"飯沼委員","text":"今のところなのですが、みなし寡婦以外はないのですか。今まで減免制度にあたった例がどのような例があるのか教えてください。"},{"i":200,"speaker":"竹田保育課長","text":"ほかにも保育料を減免する例としましては、災害等で損失を受けたとき、あるいは多額の医療費を支払ったとき、大きく世帯の収入が変動したとき等がございます。"},{"i":201,"speaker":"飯沼委員","text":"件数的にどのくらいあるのですか。例えば、年間でどのような。めったにないことですか。"},{"i":202,"speaker":"竹田保育課長","text":"今、正確な数字は持ち合わせていないのですが、項目によって多い、少ないがございます。"},{"i":203,"speaker":"塚本委員長","text":"ほかにご発言ございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":204,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、本件２議案に対する各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":205,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":206,"speaker":"浅野委員","text":"賛成します。"},{"i":207,"speaker":"飯沼委員","text":"これは一括ですか。"},{"i":208,"speaker":"塚本委員長","text":"一括です。"},{"i":209,"speaker":"飯沼委員","text":"すみません。第８９号のところは、多子減免制度や入園料の削除、この辺は評価をしますけれども、先ほどと同様で義務教育学校のところの反対を理由として反対させていただきます。\n第９３号のほうも、多子減免制度、この辺は評価をしますけれども、同様の理由で義務教育学校の設置ということで反対いたします。"},{"i":210,"speaker":"大倉委員","text":"賛成です。"},{"i":211,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":212,"speaker":"塚本委員長","text":"それでは、これより２議案につきまして、１件ずつ採決を行ってまいります。\nまず、第８９号議案、品川区保育の実施等に関する条例の一部を改正する条例について、採決いたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は、挙手を願います。\n〔賛成者挙手〕"},{"i":213,"speaker":"塚本委員長","text":"賛成多数でございます。\nよって、本案は、原案のとおり可決決定いたしました。\n次に、第９３号議案、品川区立幼稚園条例の一部を改正する条例について、採決いたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は、挙手を願います。\n〔賛成者挙手〕"},{"i":214,"speaker":"塚本委員長","text":"賛成多数でございます。\nよって、本案は、原案のとおり可決決定いたしました。\n会議の運営上、暫時休憩いたします。\n○午後 ３時０１分休憩\n○午後 ３時１５分再開"},{"i":215,"speaker":"塚本委員長","text":"それでは、これより文教委員会を再開いたします。\n────────────────────────────────────────────\n(5) 第９２号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例"},{"i":216,"speaker":"塚本委員長","text":"次に、(5)第９２号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして、理事者より説明願います。"},{"i":217,"speaker":"野呂瀬学務課長","text":"それでは、第９２号議案についてご説明いたします。\n本案は、品川区の各小・中学校に委嘱している学校医、学校歯科医、学校薬剤師が公務災害をこうむった場合の補償額を定める条例の一部を改正するものです。学校医等は開業医や薬局など、ほかに生業とする職を持つ特別職の非常勤職員であることから、別途条例で補償基礎額を定めることになっております。本条例の一部改正は、２つの内容の改正をまとめて行うものでございます。\n１つ目は、先ほど可決いただきました義務教育学校が新たに導入されることに伴い、第１条の文中の「小学校および中学校」を「小学校、中学校および義務教育学校」に改めるものです。\n２つ目は、このたび国の年金制度改正により、被用者年金制度の一元化を図るための公的年金の諸法令が改正され、本年１０月１日に施行されました。それに伴い、厚生年金保険法等の法律の条文を引用する部分に変更が生じたため、本条例の一部を規定整備するものです。\n具体的には、条例付則第８条で他の法律による給付との調整を定めており、障害厚生年金などの公的年金と、本条例による災害補償給付が同じ原因で両方支給されるような場合に、災害補償のほうを一定割合減らすという調整の仕組みを定めております。\n例えば、１枚おめくりいただきまして、新旧対照表の一番下の欄をご覧ください。下線がついておりますが、一元化法による経過措置として、一元化後も共済年金がなお効力を有するとした規定を引用し、厚生年金保険法の規定による障害厚生年金に、または平成２４年一元化法の規定による障害共済年金の文言を追加するなどの規定整備を行うものです。\nなお、このことによりまして、具体的な補償内容に影響はなく、右の欄の率に変更が生じるものではございません。\nなお、本条例は平成２８年４月１日から施行し、付則第８条の改正規定および経過措置の規定は公布の日から施行するものであります。\nご審議のほど、よろしくお願いいたします。"},{"i":218,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。よろしいでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":219,"speaker":"塚本委員長","text":"では、ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":220,"speaker":"鈴木（博）委員","text":"賛成です。"},{"i":221,"speaker":"浅野委員","text":"賛成です。"},{"i":222,"speaker":"飯沼委員","text":"年金制度の一元化に伴う部分は必要な整理と思いますが、第１条の義務教育学校の設置に対して反対をしていますので、反対をいたします。"},{"i":223,"speaker":"大倉委員","text":"賛成です。"},{"i":224,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":225,"speaker":"塚本委員長","text":"それでは、これより、第９２号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例について、採決いたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は、挙手を願います。\n〔賛成者挙手〕"},{"i":226,"speaker":"塚本委員長","text":"賛成多数でございます。\nよって、本案は、原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(7) 第９７号議案 指定管理者の指定について"},{"i":227,"speaker":"塚本委員長","text":"次に、(7)第９７号議案、指定管理者の指定についてを議題に供します。\nそれでは、本件につきまして、理事者より説明願います。"},{"i":228,"speaker":"廣田子ども家庭支援課長","text":"私からは、第９７号議案、指定管理者の指定についてご説明いたします。委員会資料としてあらかじめお配りしたＡ４、１枚の資料をご覧いただけますでしょうか。\n管理を行わせる施設につきましては、品川区平塚二丁目１２番２号に所在いたします、品川区立家庭あんしんセンターでございます。\n指定管理者の候補者につきましては、社会福祉法人福栄会。所在地は、品川区東品川三丁目１番８号でございます。\n指定期間につきましては、平成２８年４月１日から平成３３年３月３１日までの５年間を予定してございます。\n候補者の選定は、「品川区指定管理者制度活用に係る指針」に基づきまして、高齢者福祉施設や保育施設のように、運営者に連続性が要求される施設であるため、候補者を公募せずに、現指定管理者を選定候補者として特定して、選定委員会に可否について付議したものでございます。\n次に、審査の経緯でございますが、平成２７年９月１７日に社会福祉法人福栄会より指定管理者指定申請書を受理いたしまして、１０月８日、指定管理者候補者選定委員会を開催し、候補者を決定してございます。\n指定管理者候補者の選定委員会の構成は、委員長が子ども未来部長、委員は企画調整課長、子ども育成課長、子ども家庭支援課長、保育課長の４名でございます。\n次に、裏面をご覧ください。選考基準でございますが、４点ございまして、１つ目が、利用者の平等な利用およびサービスの向上を図るものであること。２番目に、適切な維持および管理を行い、管理に係る経費の縮減を図るものであること。３、管理を安定して行う物的能力および人的能力を有していること。４番目に、設置目的を達成するために十分な能力を有していること。以上の総合評価でございます。\n次に、指定管理者候補者として選定した理由でございます。１つ目が、利用者の相談に対して迅速に対応し、適切な利用およびサービスを提供しており、複雑な事情を持つ利用者に対しても信頼関係を醸成できる等高いスキルを有しているというところを第三者評価等、さまざまなものから判断してございます。\n２つ目に、母子生活支援施設では複雑な背景を持ちながら保護された母子が入所する施設であるため、安心して生活できる環境づくりが必要であり、入所母子とのつながりが大切な要素と考えてございます。そのため、これまでの実績や利用者アンケートの結果等を踏まえまして、現指定管理者は日々継続して母子の状況を把握しながら信頼関係を構築した上で適切な指導・援助を行っており、今後も連続的・継続的にサービスを提供することが望ましいと判断いたしました。\n３番目に、子育て短期支援事業等につきましては、区のこれまでの要望に応えて、新しい取組みが計画に盛り込まれる等、事業運営につきまして前向きであるというところを評価いたしました。\n今後のスケジュールについてでございますが、本件につきましてご議決をいただけましたら、議決の後、指定管理者への指定決定通知を送付し、管理運営に関する協議を行った上で、協定書を締結していきたいと考えてございます。"},{"i":229,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":230,"speaker":"飯沼委員","text":"あんしんセンターの事業は多岐にわたっていますし、職種もとても多いといったところにおいて、事業自体もとてもデリケートな事業に携わっていらっしゃるということにおいては、選考基準の3)の「物的能力および人的能力を有していること」というところにおいては、本当に経験豊かな方、継続してお仕事をしていただけるということがすごく大事であると思っています。その辺の職員の確保のことについて、問題はないかどうか、継続、定着ができているのか、離職率など、わかったら教えていただきたいと思います。正規と非正規の職員のところでわかったら教えてください。"},{"i":231,"speaker":"廣田子ども家庭支援課長","text":"まず、人的確保の部分ですが、人的部分については審議も委員会の中でされておりまして、事業が多岐にわたっておりまして、各分野において確認をしております。ひまわり荘、母子生活支援施設につきましては、ここは第一優先に福栄会で人員配置をしておりまして、過去５年間で福栄会の各施設の人事異動と定年による退職、非常勤につきましては契約期間が切れたという場合を除きまして、人員の変更等はございませんでした。\nただ、短期の子育て支援センター等の職員に関しましては、やはり職員の確保が難しいということで、途中で退職される方がいて、確保が困難で課題であるということについては認識してございます。\n離職率につきましては、過去３年間については確認してございます。平成２５年度で離職率３％、平成２６年度で１１％、平成２７年度で３％となっておりますが、いずれも短期入所等の部分の離職があったというところで、ひまわり荘については維持されていたというところで評価をしてございます。"},{"i":232,"speaker":"飯沼委員","text":"ひまわり荘のところは、定着して安定してやってくださっているということで、短期の子育て支援のところの課題というのは、どういうふうに解決されていくのか。"},{"i":233,"speaker":"伊崎子ども育成課長","text":"子育て支援センターは、子ども育成課で所管しております関係で、私のほうで答弁いたします。\n今、説明がございましたが、子育て支援センターは東京都の子ども家庭支援センターとして位置づけられておりまして、子どもと家庭に対する専門的な相談、その中には虐待への対応も含まれております。また、短期の子育て支援事業などを実施しております。こちらにつきましては、今職員の確保が課題だということがありましたけれども、若い職員がなかなか相談の現場で根づくということが、ここ数年の傾向でございますが、落ち込んだのがあるのかと捉えております。退職ということもあったということを聞いているところです。\nそちらに関しましては、子育て支援センターの職員の中で研修や人材育成といったところをもう一度きちんと見直して、人材を育てるという視点で改めて構築していこうという話を聞いているところでございます。"},{"i":234,"speaker":"飯沼委員","text":"子育て支援のところで、結構虐待の予防といった、対応的になかなか難しい、あと連携が必要だというところにおいては、ぜひ根づいてやっていただきたい、蓄積していただきたいところなのですが、この職員は正規でしたか、非正規でしたか、どちらでしたか。"},{"i":235,"speaker":"伊崎子ども育成課長","text":"子育て支援センターの虐待の対応の職員が常勤、正規でございます。"},{"i":236,"speaker":"飯沼委員","text":"大事な部署であるし、これからもますます求められていくし、経験を持って、どんどん周りにも発信しながら連携強化をしていただきたいので、ぜひ続いてお仕事をしていただけるようによろしくお願いいたします。"},{"i":237,"speaker":"浅野委員","text":"指定管理者の指定ということで伺いました。事業としては非常に多岐にわたって、難しい事業だとは思うのですけれども、ほかに候補となるような団体というのでしょうか。そういうところはあるのかということと、そして、複数あれば比較をしながらということもできると思うのですけれども、そういう意味では、そういうところがほとんど見つからない状況なので、今回はこちらに指定をされたのかということについて１点お伺いしたいです。\nそういう意味では、非常に難しい方に対応する場合もあると思うのですけれども、今までに事故というものがあったのかどうか。あったときには、どのような事故なのか。また、これから想定される危ない状況というのはある程度考えられていると思うのですけれども、そういうことについての取組みについて教えてください。"},{"i":238,"speaker":"廣田子ども家庭支援課長","text":"ほかの候補者についてでございますけれども、新規で継続性を考えなければ、ないことはないと認識しております。平成２５年に第三者評価を行っておりまして、そちらで母子のほうに母親は母親、子どもは子どもというところでアンケート等をとらせていただいております。職員の対応に対して丁寧で満足しているというところが母子ともに１００％を確保されていまして、安心して生活できるように支援がされているというところで、９割近くの回答が得られているところから、もちろんほかにもいい事業者はあろうかとも思いますけれども、毎日生活するところですので、現在入所している母子の評価を重視して、比較は今回行いませんでした。\n事故につきましては、大きな目立った事故はないのですけれども、事故というかＤＶに近い関係で、母子で入所されているのですが、父親らしき人から問い合わせが来たというリスクのことはございました。それにつきましては、泊まりをする職員の体制を増やしたり、入り口のセキュリティーを強化するということを行っておりまして、リスクを認識した時点で区のほうに連絡があって、対応についてしているという報告もございます。\nまた、リスクに対するさまざまな対応マニュアルについて、今までもあったのですが、平成２６年度に改変を行っておりまして、また新たな取組みをしたというところで、そちらを評価して対応しているところでございます。"},{"i":239,"speaker":"浅野委員","text":"確かに長きにわたってやられているということもありますので、取組みも大きな意義があったのかと思うので、よろしくお願いします。\nやはり事故については、万全の体制で捉えていると思いますが、引き続き、そこに住まわれている方や対応される方が安全であるような仕組みで、これからも継続して頑張ってもらいたいと思います。"},{"i":240,"speaker":"高橋（し）委員","text":"今、長い間と伺ったのですが、何年からずっとやられているのかということと、前回の指定管理の予算といいますか、今回は幾らになっているのかがわかればお伺いします。"},{"i":241,"speaker":"廣田子ども家庭支援課長","text":"いつからというご質問でございますが、指定管理の制度が入りました指定管理者としては平成１８年から福栄会が指定管理者となっておりまして、１期、２期で、今回は２期が終了しての選定になっております。今回、さらに選定されれば３期目になりますが、指定管理になる前に平成１４年からあんしんセンターという形でオープンしたのですが、管理委託ということで、そのころから委託という形で福栄会が受託者としてやってございます。\n予算の金額につきましては、平成２８年度につきましては予算の査定をしているところでございますが、平成２７年度につきましては、総額であんしんセンター全部になりますと、１億４,８５０万円となるのですが、金額の設定につきましては、国基準であるとか、都であるとか、保護単価を基準にしておりまして、８割近くが人件費ということになっております。保護単価の改定に伴って、予算が変わっているという状況でございます。"},{"i":242,"speaker":"高橋（し）委員","text":"平成１４年からやっているので、今お話の中では評価は高いということなのですが、やはり長く同じところがやれば、改善に対する面も甘くなっていくと思いますので、そのあたりは区がきちんと見ていっていただかないと、先ほども虐待云々もありましたけれども、ちょっとしたことが命にかかわることが多いので、ぜひそこは続けてとっているから大丈夫だというのではなくて、厳しくチェックをしていただきたいと思います。\n予算のほうはわかりました。ありがとうございました。"},{"i":243,"speaker":"伊藤副委員長","text":"こういう議案が出てきていつも思うのですけれども、指定管理者制度が導入された目的というのは、事務事業があって、それに対するコストを評価して、さまざまな民間活力を導入することで、費用を下げて効果そのものは継続していくということがあると思うのです。\n今ご説明があったように、家庭あんしんセンターは事業の継続性は十分わかるのです。だけど、ずっと福栄会なのです。だから、継続性の部分と、先ほど浅野委員もおっしゃったように、ほかの業者を入れていくところというのは、やはり品川区としては第三者的な目と言ったらいいのか、ずっと同じだったら、目的がはっきりしないわけです。要するに、複数の候補者があって、こういう理由で、結果として福栄会が選ばれたのならばある程度理解できるのだけれども、初めから事業の継続性ということをうたってこれが返ってくると、さて、それはどこまで指定管理者の内容が活かせているのかという疑問がついてくるのです。\nただ、さまざまなプライベートの話があったり、おそらく相談員の方と利用する方々との人間関係があるのでしょう。だから、それはなかなか切れないところもあるのだけれども、今聞いていると平成１４年でしたか。その年度からやっているとすれば、入居者も変わっているでしょうし、さまざまな社会情勢も変わっていく中で、なぜ福栄会なのかという疑問がつくのだけれども、改めて答弁をお願いいたします。"},{"i":244,"speaker":"廣田子ども家庭支援課長","text":"今回、公募にしないというところにあたりまして、今までの評価についても、あらかじめ洗い出しをしてございます。福栄会だからというか、今までの成果といたしまして、入所してからの入所年数等について確認してございます。平成２２年から平成２６年の５年間で、入所者が退所するまでの年数というのを確認しまして、平均で２.５年でした。入所年数が１年から５年ということで、３２世帯で平均をとっております。その中で、５年間で退所した３２世帯の中で、平成１８年入所のころの人たちは、細かく見ますと平均的に四、五年入所ということになっておりまして、平成１９年、平成２０年だと、大体３年平均で、以降二、三年で自立に持っていけているというところで、入所にあたりまして、区では今、目安としては２年で自立できるようにという支援をしております。場合によっては早く出られる場合もあれば、３年を超すということはあるのですけれども、成果として平成１８年からずっと見ていくと、ここ二、三年で目標を達成できるように積極的な支援が行われているというところで、継続していくことが効果があるのではないかというところです。\nあと、退所後のアフターケアというのを、前回の指定管理の更新のころから取組みが始まりまして、退所される世帯が希望されないとできないのですが、ルーチン化されて、退所後のアフターケアというのが具体化して計画が進んでいるところです。なので、これは継続したほうがよいのではないかという判断もございまして、今回選定するところでは、このあたりを評価したところでございます。第三者評価でも、退所後のアフターケアと職員の研修でスキルを上げようとしているところについては評価をいただいているところでございます。"},{"i":245,"speaker":"伊藤副委員長","text":"今回の本会議で指定管理者制度が、相当ほかの委員会にも付託されています。たしか１つだけ例外があったと思うのだけれども、ほとんどが旧来の事業者なのです。だから、今おっしゃったように、個々の事業を見ていれば継続性は必要であるし、特にこういう施設は、おそらくさまざまな話があるから、急に変わるとは言いにくいのだけれども、税金の公平な使用や効率化ということを考えていくと、評価をするのは難しい。難しいのだけれども、議会の立場からすると、この指定管理者制度を導入した目的というのは違うところにあるのではないかという意見がいつもついて回るので、そのことについて聞いても、なかなか答えは難しいのかもしれないけれども、お答えいただきたい。\nそれから、例えばほかの委員会で出た議案の中で、あるところでは、指定管理者の中で東京都の監査が入った等あるではないですか。本来、そういうものは品川区の委員会の中で引き継ぐべきではないですか。つまり、この施設ではないけれども、東京都に言われて、丸投げしていた実態があったとか。だから、私が思うのは、候補者選定委員会の中で、そういう実務的な面まで見ているのですかということが、いつも疑問に思っていたのだけれども、いかがでしょう。"},{"i":246,"speaker":"金子子ども未来部長","text":"指定管理者制度の根本的なところについてのお尋ねもあろうかと思います。副委員長ご指摘のとおり、指定管理者制度を５年で更新していくという意味では、極端に言うと５年で交代していくということになりますけれども、福祉施設はそういうことが適切かどうかということもあります。そういう意味では、指定管理者制度の趣旨と福祉制度をどううまくあわせていくかというのは難しい場面だとは思います。\n家庭あんしんセンターを見ますと、かなりの施設がたくさん入っている複合施設になっていまして、今お話の母子生活支援施設の部分も、なかなか５年で変わっていくというのは厳しいところもあります。\nまた、もう一つ、所管が２つに分かれているのですけれども、子育て支援センターの虐待、あるいは見守りについての対応というのも、変えていくのがなかなか難しいところでございます。私どもとしましても、本来指定管理者制度の趣旨を活かしていきたいところではありますけれども、そういうところの継続性も非常に重要視すべき施設であると思っていますので、先ほど来、課長が申し上げているとおり、第三者評価における問題、あるいは国等の補助が入っておりますから、国等の指導検査もございます。そういったところで、仮に問題があったときに、なかなか改善ができないとなれば、これは指定管理者を公募して変えていくということも必要な場面が出てくるとは思います。\nただ、現在のところ、先ほど来申し上げたとおり、現在の施設運営については特段問題なく、またさまざま改善をしようという意欲もある法人ですので、私どもは今回３期目の更新となりますけれども、今回については継続とするところが妥当かと判断したところでございます。"},{"i":247,"speaker":"伊藤副委員長","text":"そういうお考えは、よく理解できる部分はあるのですけれども、ただ、たまたま今回はこの委員会ではないのだけれども、ほかの委員会に出された案件で、東京都の監査でさまざまな実態が出てきたことがあったわけです。私としては、それは品川区が指定管理をしたわけだから、品川区のさまざまな部署で実務を確認して、評価してとおっしゃるのだけれども、東京都の監査を受けて初めてわかったということからすると、やはり品川区としてもっと頑張ってほしい。もっと言うと、はっきり調査してほしいという思いもあるのです。\nだから、福栄会が悪いということではなくて、この制度自体を活かしていくことを考えていくと、ほかの案件ですけれども、品川区としては、外から、東京都から言われて、ある意味悔しいと思わなければいけないと思うのです。さまざまな指定管理をする中で、その業者をしっかりと把握して、業務内容を把握して対処していってください。その体制を強化していただくようにお願いしたいのだけれども、いかがでしょうか。"},{"i":248,"speaker":"金子子ども未来部長","text":"私ども、指定管理者に関しては、毎年モニタリングということでチェックをしております。今、さまざま副委員長からご指摘いただきましたけれども、仮に運営上の問題があるとすれば、そういうところで、あるいは日々の業務内容をチェックしている中で、あるいは区民と接触している中で、そういう問題点を区が初めに把握しなければいけないことだと思っています。そういう意味では、私どもとしましても、福栄会はこれ以外にもいろいろ仕事の関係がありますので、さまざまなところでいろいろなチャンネルを使って情報を得ながら、そういう意味では万が一、外側から指摘をされるということはないように、内側からの、我々のほうでの接触の中からさまざまな日ごろの問題意識を持って、課題があれば速やかに把握できるという日常的な運営の仕方をしていきたいと考えてございます。"},{"i":249,"speaker":"伊藤副委員長","text":"よろしくお願いします。"},{"i":250,"speaker":"塚本委員長","text":"ほかにございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":251,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来。"},{"i":252,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":253,"speaker":"浅野委員","text":"賛成します。"},{"i":254,"speaker":"飯沼委員","text":"賛成します。"},{"i":255,"speaker":"大倉委員","text":"賛成です。"},{"i":256,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":257,"speaker":"塚本委員長","text":"それでは、これより、第９７号議案、指定管理者の指定についてを採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":258,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(10) 第８４号議案 平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）"},{"i":259,"speaker":"塚本委員長","text":"次に、(10)第８４号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）を議題に供します。\nそれでは、本件につきまして、理事者より説明願います。"},{"i":260,"speaker":"伊崎子ども育成課長","text":"それでは、第８４号議案、平成２７年度品川区一般会計補正予算、子ども未来部所管分についてご説明いたします。\n補正予算書の１４ページをお開きください。第３款民生費、２項児童福祉費、１目児童福祉総務費につきましては、９,０７３万７,０００円を追加し、４５億８,７６０万９,０００円とするものです。\n右側１５ページの説明欄をご覧ください。保育事業助成追加分として、認証保育所運営費等助成を９,０７３万７,０００円計上してございます。\n１ページおめくりいただきまして、１６ページ、２目児童措置費につきましては、１億８,３３８万５,０００円を追加し、１３０億７９０万５,０００円とするものです。\n右側１７ページの説明欄をご覧ください。児童保育委託追加分として、１億８,３３８万５,０００円計上してございます。内訳としましては、区内私立保育園経費として、１億４,５４９万４,０００円、小規模保育事業等経費として、３,７８９万１,０００円でございます。合計しまして、補正額は２億７,４１２万２,０００円で、予算額は計３０５億６,１３６万２,０００円となります。\nなお、歳入でございますが、１０ページ、１１ページに歳出見合いで補助金の増額および財源更正がございます。"},{"i":261,"speaker":"竹田保育課長","text":"保育課所管分についての内容をご説明いたします。\n１目児童福祉総務費、９,０７３万７,０００円の内訳、７,２３４万８,０００円についてですが、平成２７年度より東京都の補助事業として、保育士キャリアアップ補助事業が創設されました。この補助金は、保育士等が保育の専門性を高めながら、やりがいを持って働き、それにより保育のサービスの質の向上を図ることを目的とするものです。補助金の使途は、賃金改善に限定して、４月にさかのぼって補助を実施するものでございます。\nまた、２,８５８万９,０００円についてですが、こちらも平成２７年度から東京都により保育力強化事業補助金が創設されました。この補助金により、認証保育所のさまざまな取組みに対して助成を行うことにより、認証保育所全体の保育サービスの向上を図るものでございます。\nまた、本補助金には第三者評価受審費助成が含まれていることから、当初予算にて計上しておりました同内容の１,０２０万円につきましては重複することから減額いたします。\nまた、２目児童措置費につきましては、１億８,３３８万５,０００円の内訳、１億４,５４９万４,０００円は、区内私立保育園に対する経費であり、認証保育所と同様に７,７６２万２,０００円が保育士等の賃金改善に使途を限定して、４月にさかのぼって補助を実施するもので、６,７８２万２,０００円が認可保育所のさまざまな取組みに対して助成し、サービスの向上を図るものでございます。\nまた、３,７８９万１,０００円は、小規模保育事業に対する経費であり、認証保育所と同様に２,６６０万１,０００円が保育士等の賃金改善に使途を限定して、４月にさかのぼって補助を実施するもので、１,１２９万円が小規模保育事業のさまざまな取組みに対して助成し、サービスの向上を図るものでございます。"},{"i":262,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":263,"speaker":"飯沼委員","text":"今ご説明いただいた保育事業助成追加分、児童保育委託追加分、これは都の補助事業というのは、全く新しく今回出てきた助成ということですか。それで、この中身的には、認証保育所と区内私立保育園、小規模保育事業となっていますけれども、これは事業をやっていれば、ある程度平等に１人幾らぐらいといって分けられるものなのか、これを具体的にやらないと配分されないとか、何か制約があるかどうか教えてほしいです。\nあと、保育力強化事業助成というのが、さまざまな取組みに充てられるということなので、さまざまの中身を教えていただきたいと思います。"},{"i":264,"speaker":"竹田保育課長","text":"基本的には、区内の保育施設は全て該当するものと考えております。\nまず、保育士等キャリアアップ補助事業ですが、こちらにつきましては認可保育所、認証保育所、認定子ども園等、各保育所ごとにそれぞれ園児の人数の規模に合わせて、さらに各園児の年齢に合わせて単価が決まっておりますので、その人数や園の規模に基づきまして算出するものでございます。\nそれから、さまざまな取組みということで具体例でございますが、例えば一時預かり事業を実施している、外国人児童の受け入れを行っている、アレルギー児童の対応を行っている、地域子育て支援の事業を行っているなどの項目について加算するものでございます。"},{"i":265,"speaker":"飯沼委員","text":"都のところから新しく事業ということなのですが、一般財源を減額した理由というか、両方で手厚くしたらありがたいなと思ったのですけれども、その辺の考えをお聞かせください。"},{"i":266,"speaker":"竹田保育課長","text":"今回減額しておりますのは、第三者評価受審費助成でございます。同様のものを当初予算で計上してございます。ただ、今回、東京都から１０分の１０の補助が出ることになりましたので、同一施設に同じ項目で二重に補助する形になりますので、当初予算で計上しておいた部分につきましては減額することといたしました。"},{"i":267,"speaker":"飯沼委員","text":"後から都から財源がついたりすると、そうやって浮くお金も出てくるということですね。わかりました。ありがとうございます。"},{"i":268,"speaker":"鈴木（博）委員","text":"これは、保育課長に前も何回か質問してお答えいただいたと思うのですけれども、今保育士というのは非常に足りないのです。それで、各地方自治体でも奪い合いになっている。品川区の公立保育園だけ保育士を確保しても、裾野の民営の保育園で保育士を確保できなければ、絵に書いた餅になる。\n品川区で、例えばほかの区や神奈川県などと当然競合しているわけです。品川区では、僕は全て区営がいいとはちっとも思っていないのですけれども、区立でも、ほかの保育園でも、品川区で保育士を集めるにはどういうストラテジーをお持ちなのか。お金を上げれば、ほかのところも上げるし、今の保育士はドライですから、お金が高いほうにどんどん流れていってしまうから定着しないと思うのです。その辺はどういうお考えでいますか。"},{"i":269,"speaker":"竹田保育課長","text":"委員おっしゃるとおり、賃金は保育士が働く上での大きなモチベーションでございますが、それと並行しまして、保育士のモチベーションとしまして、高い質の保育をやっている施設で働くことによって、自分の持っているキャリアを上げるといいますか、資質を向上させたいという、一方でそういう気持ちがある方が大勢いらっしゃいます。ですから、賃金改善を行うとともに、高い質の保育を実施することによって、子どもたちも育てる、保育士も育てるという環境のもとで実施することによって、品川区の保育を目指していただける保育士がいると思います。\n具体例を申し上げますと、例えば任期付き職員というのですが、産休の代替職員でございますが、結構遠方から品川区の保育所で働いて、ぜひ品川区の保育を身につけたいとお考えの方も大勢いらっしゃいますので、まずは高い質の保育を提供することが我々の使命だと考えております。"},{"i":270,"speaker":"鈴木（博）委員","text":"すばらしいお話を聞いたのだけれども、品川区の保育がそんなにすばらしいとは、確認して、それほど詳しくは知らなかったのです。品川区の保育が周りに冠たるいいところというか、売りどころ、セールスポイントはどんな点がすばらしいのですか。"},{"i":271,"speaker":"竹田保育課長","text":"少し手前みそになりますけれども、具体的に大学の先生に監修いただきまして、『のびのび育つ しながわっこ』という冊子を継続的に発行しております。その先生のお言葉をかりると、全国の自治体でこういう形で詳しく、しかも冊子のような形にしているのは品川区だけではないでしょうかというお言葉もいただいております。\nまた、一部の事例ですけれども、品川区を諸事情で退職した職員が、また品川区で働きたいということで戻ってくるような保育士もいます。ぜひ保育士の視点から見て、品川区の保育所で働きたいという保育士が増えるように、我々も努力していきたいと考えております。"},{"i":272,"speaker":"鈴木（博）委員","text":"非常にすばらしい話なので、ぜひそれを推し進めて、品川区保育所の名声をもっと高めてください。"},{"i":273,"speaker":"高橋（し）委員","text":"キャリアアップということは、保育士の賃金をアップすることに使うわけですけれども、それが各私立保育園や認証保育所のところで、個人個人がこれだけお給料が上がったというのは、何らかの形で区はチェックができるのでしょうか。"},{"i":274,"speaker":"竹田保育課長","text":"このスキームにつきましては、各保育所ごとに賃金体系が違いますので、算出根拠に基づきまして、一括して保育所にお渡ししまして、その金額がどんなふうに配分されたのかということを実績報告を上げていただくことによって確認しております。"},{"i":275,"speaker":"高橋（し）委員","text":"その実績報告というのは、そのお金は、今まで人件費でこれだけだったけれども、それをこれだけ増やしたという形で報告されるのですか。"},{"i":276,"speaker":"竹田保育課長","text":"今回、補助金としてお渡しした金額の詳細についての明細をいただくものでございます。"},{"i":277,"speaker":"高橋（し）委員","text":"それが人件費に回らないで、全体の別のところにいくということが、今のお話だとあり得ないということで認識してよろしいですか。\n〔「はい」と呼ぶ者あり〕"},{"i":278,"speaker":"伊藤副委員長","text":"今の話を聞いていて、非常にすばらしいことだと思うのですけれども、継続はできないのですか。つまりキャリアアップや上乗せのところについて、東京都の補助金は単年度だけなのですか。わかりますか。"},{"i":279,"speaker":"竹田保育課長","text":"今回、国で公定価格というものが示されまして、保育士の賃金が大きく改善されました。認証保育所などは、東京都の独自事業ですので、公定価格を受けない部分もあります。公定価格に限定する形で、東京都も賃金改善という形で、今回補助金が創設されたと考えております。"},{"i":280,"speaker":"伊藤副委員長","text":"確かに東京都のことですから、課長ではなかなか答えにくいと思うのだけれども、現場としては、大変な中で当然喜んでいらっしゃるわけでしょう。だから、やはりこれは継続してもらいたいと思うわけであって、補助金という形ではなく、例えば、それこそ財調算定にしていく。おそらく品川区だけの話ではないわけでしょう。全ての市区町村にかかる話であるだろうから、それはさまざまな部課長会議等の中で、これはできれば財調算定に入れていただいて、自動的にお金が入ってくる仕組みを構築していってほしいと思うのだけれども、品川区のお考えを聞かせてください。"},{"i":281,"speaker":"竹田保育課長","text":"そもそも今回創設するにあたって、東京都が保育士の実態調査というものを昨年３月に行っております。その結果によりますと、約２割の保育士が退職している。６５％の方が給料が安いということを理由の１つにしているという実態があって、東京都も今回事業の創設に至ったと聞いております。この実態を東京都にも機会を捉えてお伝えしながら、保育士不足というのは続いており、今後も継続して続くと思いますので、この補助金を維持していけるように東京都にも訴えていきたいと考えております。"},{"i":282,"speaker":"伊藤副委員長","text":"要は補助金だと、単年度で終わってしまうと嫌なのです。さまざまな保育現場の環境を改善していくためには、ある程度安定したものをやっていっていただきたいということでお話をさせていただいています。もちろん課長が決めるとは思っていないけれども、さまざまな部署、課長会、部長会等々で指摘をよろしくお願いいたします。"},{"i":283,"speaker":"塚本委員長","text":"ほかにございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":284,"speaker":"塚本委員長","text":"では、ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":285,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":286,"speaker":"浅野委員","text":"賛成します。"},{"i":287,"speaker":"飯沼委員","text":"賛成します。"},{"i":288,"speaker":"大倉委員","text":"賛成です。"},{"i":289,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":290,"speaker":"塚本委員長","text":"それでは、これより、第８４号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）について採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":291,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n以上で議案審査を終了いたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n(1) 平成２７年請願第２８号 品川区私立幼稚園児保護者負担教育費軽減の為の請願"},{"i":292,"speaker":"塚本委員長","text":"次に、予定表２、請願・陳情審査を行います。\n初めに、(1)平成２７年請願第２８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願を議題に供します。\n本件は、初めて取り上げますので、書記に朗読させます。\n〔書記朗読〕"},{"i":293,"speaker":"塚本委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者の説明を求めます。"},{"i":294,"speaker":"竹田保育課長","text":"平成２７年請願第２８号、品川区私立幼稚園児保護者負担教育費の軽減の為の請願につきましてご説明させていただきます。\nまず、請願項目１の保護者補助金の所得制限の撤廃についてでございますが、保護者補助金は私立幼稚園に通わせている保護者の方々の経済的な負担を軽減し、幼児教育を受けることができる環境を確保するという目的の制度でございます。このため、一定の所得制限が必要と考えておりますが、区は従来から私立幼稚園の保護者および私立幼稚園協会に対しまして、さまざまな経済支援を実施し拡充してまいりました。平成２２年には保護者補助金の所得制限を緩和し、区民税の所得割額が２１万６,７００円から２６万３,５００円までの方に対象を広げ、平成２４年度には３３万４,１００円まで、さらに平成２６年度には、３７万円までの方に対象を広げたところでございます。また、就園奨励費につきましては、平成２６年度より幼稚園に同時就園している第二子以降と小学校１年生から３年生に兄や姉がいる場合の園児保護者の所得制限を撤廃しております。\n今後も、保護者負担の軽減と幼児教育の充実のため、教育費の家計に及ぼす影響や保護者の方の負担の状況も十分配慮しながら、適切な補助を行ってまいりたいと考えております。\nなお、平成２６年度の就園奨励金の受給者は１,９６１人、保護者補助金は２,２７４人、また入園料補助金につきましては、所得制限はございませんが、１,２９７人の方に交付いたしました。これらの総額６億４,４００万円余を補助しているところでございます。\n次に２点目、私立幼稚園のさらなる支援・助成金の増額、また母の会連合会への助成金の要請でございます。現在、私立幼稚園に対する補助金といたしましては、幼稚園設置者に対するもの、私立幼稚園協会に対するもの、また各幼稚園の預かり保育事業に対するものの３点が主な補助対象でございます。各幼稚園設置者のための補助金といたしましては、運営費、研修費、教材費からなります振興費の補助金のほか、園児の健康管理増進費、心身障害児教育事業補助金、それから防災安全対策補助金など、区単独で各幼稚園に対しまして、直接に補助しているところでございます。\nなお、心身障害児教育事業補助金につきましては、平成２７年度より１２５万円増額しているところでございます。\n次に、私立幼稚園協会に対する補助金につきましては、特別支援教育の研修や講演などの充実を図るためなどに、平成２７年度より４３万円増額して、年額５５０万円を助成しているところでございます。この中から、母の会連合会の事業にも経費が充当されていると伺っております。\n今後も、子育てにかかる費用の経済的な負担を軽減し、子育て世帯を経済面から支援し、安心して子育てをしながら住み続けられることを目指していきたいと考えております。"},{"i":295,"speaker":"塚本委員長","text":"説明が終わりました。\nこれより質疑を行います。ご発言願います。"},{"i":296,"speaker":"石田（ち）委員","text":"基本的なところで申しわけないのですけれども、入園料補助金と園児保護者補助金、そして幼稚園等就園奨励費補助金で、区が出しているものと国や都が出しているものもあると思うのですけれども、この３つの補助金の出処を教えていただきたいのと、どれだけ、どういった率で出されているのか、わかれば教えていただきたいと思います。"},{"i":297,"speaker":"竹田保育課長","text":"就園奨励費補助金につきましては、国の事業でございます。\nそれから、園児保護者補助金につきましては、東京都の基準に、さらに区で上乗せして支出しているものでございます。こちらはそれぞれ所得に応じて、あるいは第何子かということによりまして、補助金額が決まっているものでございます。\nまた、入園料補助金につきましては、お一人につき１０万円を上限に補助しているものでございます。"},{"i":298,"speaker":"石田（ち）委員","text":"入園料補助金がどこからで、もう一回分けて説明していただきたいのです。入園料補助金と保護者補助金、そして就園奨励費補助金を、わかりづらかったので、もう一回、ごめんなさい。"},{"i":299,"speaker":"竹田保育課長","text":"ゆっくり申し上げます。少しわかりにくかったと思うのですが、正式名称は、幼稚園等就園奨励費補助金と呼んでいるのですが、こちらは国の制度でございます。\nそれから、園児保護者補助金というのが、東京都の補助金に、さらに区が上乗せしている補助金でございます。\nそれから、入園料補助金は、区が単独で行っている補助金でございます。"},{"i":300,"speaker":"石田（ち）委員","text":"幼稚園等就園奨励費補助金は、国だけで出されているということでいいですね。そうすると、請願の文章の中に、平成１６年度には就園奨励費補助金について増額してもらえたというところは、国が増額したということになるということでいいのでしょうか。"},{"i":301,"speaker":"竹田保育課長","text":"すみません。どこの部分ですか。"},{"i":302,"speaker":"石田（ち）委員","text":"ごめんなさい。請願文の２段落目というのでしょうか。一番上が大震災からということで、次の段落の子どもたちがお世話になっておりますというものの次、３番目だ。幸いにしてというところから始まる文章の中ほどに、平成１６年度には就園奨励費補助金について、もろもろあって、増額していただきとあるのですけれども、これは国が増額した。入園料補助金のところは区が増額したということでいいのでしょうか。"},{"i":303,"speaker":"竹田保育課長","text":"就園奨励費補助金につきましては、原則、国の補助金でございますが、区も一定程度補助を出しているものでございます。\nそれから、先ほどから申し上げているとおり、園児保護者補助金については、こちらにつきましても、東京都の基準にさらに区が一定程度上乗せしている補助金でございます。"},{"i":304,"speaker":"石田（ち）委員","text":"幼稚園等就園奨励費補助金の件は、品川区と国の補助金から交付されていますと思っていいのでしょうか。"},{"i":305,"speaker":"塚本委員長","text":"一部を区も負担しています。"},{"i":306,"speaker":"石田（ち）委員","text":"一部負担。すみません。わかりました。"},{"i":307,"speaker":"飯沼委員","text":"ご説明を聞いて、この本文からすると、この間、所得制限はあるものの、対象の拡大が行われてきているというところは、一定受けとめるのですけれども、昨今のいろいろな経済的事情もあって、さらなる助成という意味では、所得制限の撤廃をということが第１点目に書かれているのです。子育て支援の経済的支援はなかなか枠組みがかっちりしていてあまり広がっていないのですけれども、所得制限を設けている理由。先ほど少しおっしゃったのですが、もう一度、なぜ所得制限がここにかかっているのか教えていただきたいと思います。"},{"i":308,"speaker":"竹田保育課長","text":"品川区の所得の分布を見ますと、さまざまな所得の方がいらっしゃり、高額納税者の方も当然いらっしゃる中で、こういう補助金制度というのは、一定の所得制限が必要だと考えております。平成２６年度に拡大しまして、園児保護者の約７０％を目標に拡大したところでございますので、今後も適切な支援をしていきたいと考えております。"},{"i":309,"speaker":"飯沼委員","text":"今の言葉をいただいた部分では、これからも拡大していくという姿勢で受けとめて、今７０％を目標と言っていますけれども、現在、所得制限で助成が受けられていない方はどのくらいいらっしゃるのか。その方に助成をするとなると、どのくらい金額がかかるのでしょうか。わかったら教えてください。"},{"i":310,"speaker":"竹田保育課長","text":"園児保護者補助金をご説明しますと、平成２６年度は区内の園児総数が３,４４０人でございます。平成２６年度に補助金を受けられた方が２,２７４人でございますから、その差が１,１６６人の方が対象ではなかったというところでございます。\nどのぐらいの経費かというのは、計算してみないと出ないところで、すぐには出ません。すみません。"},{"i":311,"speaker":"飯沼委員","text":"あともう一点、ここに所得制限導入以来、公私立幼稚園における教育費負担の格差が拡大しておりますと書かれているのですけれども、公私立の教育費の負担の格差というのは、現状においてどう捉えていらっしゃるのか伺います。"},{"i":312,"speaker":"竹田保育課長","text":"公立保育園につきましては、従来は８,０００円か、あるいは免除という体系でございました。今回、第２回定例会でご議決いただきまして、所得に応じた７段階のご負担をいただくという内容に変更いたしましたので、来年４月以降については、公立幼稚園に通われる方につきましても一定のご負担をいただく形になりましたので、一律に広がっているとは認識していないところでございます。"},{"i":313,"speaker":"飯沼委員","text":"多分、これを取り組まれたときには、公立の幼稚園の保育料の改正の中身は伝わっていないとは思うのですけれども、一律に広がってはいないと。私たちは公立の幼稚園の保育料の値上げのときに、公私立の格差があって、高い負担があるほうに合わせるのではなくて、低いほうに合わせてほしいという要望を出させていただいたのです。この本文の終わりのほうにもかなり教育の負担感があるということが書かれていますけれども、共働きや片働きもそうですけれども、保育園に預けていらっしゃる方も、幼稚園に預けていらっしゃる方も、子育て世代は今の増税感も強いし、教育、保育、子育てにかかるお金の負担増を本当に感じておられると思うのです。\n特に年少扶養控除がなくなって、増税になった後、児童手当のお金も減っていますし、児童手当も所得制限がついているのです。ひっかかった人は一律５,０００円しかいただけないという中身で、消費税８％でも大変なのに、また近く１０％ということで、とにかく出ていくものばかりで大変だという意見がいっぱい出されている中で、本当は公立と私立の格差を見るのではなくて、どちらも負担がなくなる方法、所得制限をなくしていく方法というものが、ここに切実に出ていると思うのです。\n先ほど、予算を伺ったのは、現状、これに負担がかかっているのは幾らなのですか。その辺と、私はそんなに莫大なお金がかからなくても、幼稚園のところは毎年出されている請願だし、毎年所得制限をとってほしいと、本当に切実な要求だと思うので、国と都と区のかかわりが、いまひとつどのくらいの負担割合なのか見えてこないのですけれども、ぜひ努力ができる品川区であると思うので、努力してほしいと思うのです。どうでしょうか。"},{"i":314,"speaker":"竹田保育課長","text":"まず、予算の今までの経緯でございますが、先ほどの就園奨励費補助金と園児保護者補助金を足した金額の推移でございますが、平成２４年度は５億４,９３５万４,５００円、平成２５年度が５億２,２６０万９,９００円、平成２６年度におきましては、６億４,４４９万４,６００円ということで、区の負担は歳出拡大等に伴いまして、区の負担も増えているところでございます。"},{"i":315,"speaker":"飯沼委員","text":"なかなか区のところも少しずつ増えている部分もあるので、努力をしてくださっているという面では評価がされると思いますけれども、やはり子育て支援のところ、少子化の問題もいろいろ言われていますし、切実な請願なので、どうしたらこの支援ができるのかというあたりを考えていただきたいと思います。\nここには書かれていないのですけれども、ＯＥＣＤの調査によると、教育、子育て支援のお金が国や自治体から出されている財源的な面が、ＯＥＣＤの３カ国の中で日本は最低の額しか出ていないという中身。やはり国のところもそういった状況である中で、品川区は、今回いただいた報告の中の８月末日現在の出納検査の結果という最後に、基金の関係調書というところで、８１２億８,３００万円、かなり大きな額で増えているというところで、基金が増えている。子育て支援、負担、負担と言いながらも、実際、最終のところでお金が増えているというところでは、子どもにかけるお金というのは、子どもが元気に育つし、お父さん、お母さんたちも元気に暮らしていけて、将来に明るい展望が持てると思うので、ぜひこの辺のより一層の努力をお願いしたいと思います。"},{"i":316,"speaker":"塚本委員長","text":"ほかにご発言ございませんか。\n〔「なし」と呼ぶ者あり〕"},{"i":317,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、質疑を終了いたします。\nそれでは、平成２７年請願第２８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願について、ご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらか、まず、自民党・子ども未来からご発言願います。"},{"i":318,"speaker":"鈴木（博）委員","text":"結論を出す。"},{"i":319,"speaker":"浅野委員","text":"結論を出す。"},{"i":320,"speaker":"飯沼委員","text":"結論を出していただきます。"},{"i":321,"speaker":"大倉委員","text":"結論を出すでお願いします。"},{"i":322,"speaker":"高橋（し）委員","text":"結論を出す。"},{"i":323,"speaker":"塚本委員長","text":"それでは、本件については、結論を出すでご意見がまとまったようですので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":324,"speaker":"塚本委員長","text":"それでは、本件については、結論を出すに決定いたしました。\n採決に入ります前に、本件につきまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":325,"speaker":"鈴木（博）委員","text":"深刻な経済状況の中、幼稚園に在園されている園児の保護者の方は非常にご苦労されていると思うので、非常にお気持ちはわかりますので、採択したいと思います。"},{"i":326,"speaker":"浅野委員","text":"賛成します。採択。\n保護者の方、大変な中で子どもを育て、また保育料もかかっているということもありますが、補助金を出すことによって、教育関係もいろいろな事業もできるようになるし、またいろいろな取組みもできるようになると思いますので、またよろしくお願いします。"},{"i":327,"speaker":"飯沼委員","text":"採択。"},{"i":328,"speaker":"大倉委員","text":"採択でお願いします。\n本旨の格差是正と保護者の経済的負担の軽減というのは、ぜひ図っていただきたいのと、教育内容の充実や、私立保育園の振興というのも、支援をしていくことが大切だと考えますので、採択でお願いいたします。"},{"i":329,"speaker":"高橋（し）委員","text":"私立の幼稚園には、就学前の保育の多くの部分を担っていただいていて、また保護者の方々は、この中にあるように、今さまざまな事情でご苦労されていると思います。多様な教育ということで、私立幼稚園の位置づけも重要なものだと思いますので、採択といたします。"},{"i":330,"speaker":"塚本委員長","text":"それでは、平成２７年請願第２８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願について、お諮りいたします。\n本件を採択することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":331,"speaker":"塚本委員長","text":"ご異議なしと認めます。\nよって、平成２７年請願第２８号は採択と決定いたしました。\n────────────────────────────────────────────\n(2) 平成２７年請願第３２号 認可保育園・区立幼稚園保育料値上げとすまいるスクール有料化の中止を求める請願"},{"i":332,"speaker":"塚本委員長","text":"次に、(2)平成２７年請願第３２号、認可保育園・区立幼稚園保育料値上げとすまいるスクール有料化の中止を求める請願を議題に供します。\n本件は、初めて取り上げますので、書記に朗読させます。\n〔書記朗読〕"},{"i":333,"speaker":"塚本委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者の説明を求めます。"},{"i":334,"speaker":"竹田保育課長","text":"平成２７年請願第３２号中、請願項目１、認可保育園保育料、請願項目２、区立幼稚園保育料の請願につきましては、私からご説明させていただきます。\nまず、請願項目１、認可保育園保育料についてでございますが、保育園保育料を改定した理由および内容ですが、本年４月に施行された子ども・子育て支援新制度において、保育園保育料は子ども・子育て支援法施行令で定める額を上限に、住民税額による応能負担への変更が示されました。品川区では、平成２７年度につきましては、周知期間が短いことから、保育園保育料につきましては従前どおり、所得税額による階層区分に基づき決定しておりましたが、平成２８年度より所得税から住民税額による階層区分の保育料とし、新年度における住民税額への切り替えは９月といたしました。\nまた、多子減額の対象となる世帯の第一子の児童年齢を現在の５歳児から小学３年生までに拡充し、第二子以降の児童にかかる保育料を軽減する多子軽減制度を拡充すること、またおおむね１０％の保育料の引上げを行い、保育料を保護者の負担能力に応じたものに改定することといたしました。\n経過措置といたしましては、おおむね１０％の保育料の引上げについては、平成２８年度中に限り、おおむね５％の保育料の引上げを行うこと、所得税から住民税額による算定基礎の変更については、平成２８年４月から８月に限り、平成２８年４月の住民税を基準とした階層と平成２８年３月の所得税を基準とした階層と比較して、新階層の方が階層が上がる場合は、旧階層に相当する新階層の保育料を適用することといたしております。\nこの改定により、区歳入は所得税から住民税の算定基礎の変更によりマイナス２％、多子減額の対象拡大によりマイナス９％、現行保育料を１０％上げても、合計でマイナス１％と試算しており、全体として利用者負担が増加するものではないと考えております。\n次に、請願項目２、区立幼稚園の保育料についてでございますが、改定理由および内容ですが、請願項目１でご説明したとおり、子ども・子育て支援新制度の考え方に基づき、階層区分を現在の２区分から住民税額による７区分の保育料とするとともに、入園料を廃止するものでございます。\n経過措置といたしましては、平成２７年度の在園児については、従来額と同額とすること。平成２８年度新規入園児は従来額と比較し、保育料が上がる場合は、従来額から上げ幅を半額といたします。本改定についても、保育料を保護者の負担能力に応じたものに改定するものであると考えております。"},{"i":335,"speaker":"伊崎子ども育成課長","text":"それでは、私からはすまいるスクールについてご説明をいたします。\nまず最初に、すまいるスクール事業につきましては、事業開始時から参加費として利用料をいただいておりますので、今回の制度の見直しにより有料化を始めるということではございません。現在は、年額利用料５５０円、保険料６５０円の合計１,２００円のご負担をいただいております。\n今回の制度の見直しは、保護者の方からのご要望に応じて、利用時間の延長や間食の提供を実施、また受益者負担として総経費のうち一定のご負担をいただくことを目的に利用料の見直しを行うもので、第３回定例会で条例を可決していただいております。\n１７時までの利用料は月額２５０円、１８時までの利用料が月額３,２５０円、１９時までは月額４,２５０円とする予定でございます。金額につきましては、以前実施しておりました学童保育クラブの利用料、月額３,０００円や、現在の他区の状況を勘案して、負担が多額にならないように設定したものでございます。\nなお、減額・減免制度についても現在検討を進めているところでございます。"},{"i":336,"speaker":"塚本委員長","text":"説明が終わりました。\nこれより質疑を行います。ご発言願います。"},{"i":337,"speaker":"石田（ち）委員","text":"認可保育園の保育料のことですけれども、前までの説明で住民税に算定方式を変えていくことと、多子減額で区の収入が１１％減。それを１０％の保育料の改定でマイナス１％になるから、値上げではないということをこの間もずっと答弁いただいているのですけれども、そうすると、保護者負担が上がる人はいないということなのですか。値上げではないというのは、保護者負担が上がるということは値上げだと思うのですけれども、値上げではない、改定だということをずっとおっしゃられているのですけれども、今回の改定によって保護者負担が上がる、値上がる方はいるのでしょうか、いないのでしょうか。そこを伺いたいと思います。"},{"i":338,"speaker":"竹田保育課長","text":"さまざまなご家庭の形態、あるいは所得があると思いますので、上がる方、下がる方は当然いるものでございます。ただ、全体としまして、先ほども申し上げたとおり、マイナス１％と試算しておりますので、全体として利用者負担が増加するものではないと考えております。"},{"i":339,"speaker":"石田（ち）委員","text":"全体としてということです。上がる人もいて、下がる人もあわせると、全体でいくと値上げではないという、すごくおかしな説明だと、私は聞いていて思うのです。自分が値上がる保護者であれば、もう値上がりだという受けとめですし、値上げを中止してほしいという思いは当然だと思うのです。\nこの間、総合戦略で、区も人口ビジョンでアンケートをとられています。その中でも、希望する子どもの数が２人以上ほしいという方が８割を超えている。さらに、希望する２人以上の子どもを産める状況ですかと聞くと、厳しいと。では、その厳しい理由は何ですかというところでは、出産、子育て、教育にお金がかかり過ぎるから産めないといったことが、区の調査でも明らかになっているというところで、区もそれに対して不安の解消と負担の軽減が必要だと答えられているのです。\nですので、今回の保育料の値上げは、子育て世代にとって、まさに負担だと思うのです。そして、年少扶養控除は廃止されているし、この文の中にもありますけれども、消費税の増税も待ち構えているという状況で、これ以上の負担増は本当に厳しい。子どもを産めない状況だということだと思うのです。負担軽減が必要だと区も述べていることに対して、この保育料値上げとの関係をどう考えるか、伺いたいと思います。"},{"i":340,"speaker":"竹田保育課長","text":"少子化社会に対応していくということは、大変重要な問題だと考えております。今回の改定におきましても、第二子以降の対象者を拡大すべく、５歳児から小学３年生までに拡大し、第二子は半額、第三子については免除という形で課税しておりますので、少子化社会に対応した保育料になっていると考えております。"},{"i":341,"speaker":"石田（ち）委員","text":"多子減額を拡大しているというところですけれども、延ばしたのは３年間です。歓迎はしますけれども、それで２人、３人産めることに対応していると私は感じないです。思わないです。それで、私たちもこの間言っているのですけれども、多子減額しているのですが、それに９％の区のマイナスがある。しかし、それを保育料の１０％で補っているという仕組みというか、区の言い分というのが、子育てする皆様で多く産む人の保育料も賄ってくださいという、本当にひどい仕組みだと思うのです。\n今、課長も少子化に対応していくことは大事だとおっしゃったのですけれども、多子減額されることは歓迎するのですけれども、そのための保育料の値上げといっても過言ではない値上げが、少子化にさらに拍車をかけると私は思うのです。その辺の見解を改めて伺いたいと思います。"},{"i":342,"speaker":"竹田保育課長","text":"今回、同時に行いましたので、誤解をされる方もいらっしゃると思うのですが、そもそも保育料につきましては、全体の方を対象とする改定につきましては、平成１６年に改定をして以来の改定でございますので、１０年近く経過しているということで、保育料の改定は必要なものと考えておりまして、今回改定させていただきました。\nまた一方で、少子化社会に対応することも必要と考えておりまして、一方で多子減額の拡大も行ったものでございます。\n図らずも同時ということでございまして、埋め合わせというご指摘は当たらないと考えております。"},{"i":343,"speaker":"石田（ち）委員","text":"保育料の値上げを値上げでないと言う品川区に対して、父母の皆様は、今でも高い保育料をさらに上げるのかということで怒りの声を寄せているわけです。ですので、値上げではなく値下げこそ必要だと私は思います。\nそれで、すまいるスクールのところなのですけれども、今まで利用料が無料だったものが有料になったと。この値上がるということを保護者の方々は聞いて、率直に何でと。無料だったものが何で有料になるのかというのを率直に感じるという声を寄せていただきました。そこをもう一回、何で有料になるのかというのを伺いたいのと、有料にされた分のお金というのは、何に使われるのですかという疑問もすごく多いのですけれども、そこも伺いたいと思います。"},{"i":344,"speaker":"伊崎子ども育成課長","text":"まず、冒頭に申し上げましたように、有料になるというご指摘ですが、これまでも年額、保険料も合わせまして１,２００円という負担はいただいておりました。決して無料の事業ではございません。ただ、その金額が全体の運営経費、平成２６年度決算で１１億１,４００万円のうち、利用料と勉強会の経費を含めましても、１,５００万円ということで、非常に保護者の方の負担が少ないという状況でずっとやってまいりまして、やはり受益者負担という視点から一定のご負担はいただくべきであろうということが１つございます。\n今回は、利用料の値上げだけを行ったということではなく、利用者の方のご要望にお応えして、朝の開園時間、長期休業日、土曜日等、学校が休みの日の朝の開園時間を９時から８時１５分に引き上げたこと、それから、帰りのおしまいの時間も就労家庭については、１年生から３年生までに限定して、夜６時から７時までに延長したということで、総経費ももちろん増額を見込んでおります。\nその中で、最後のご質問で、何にお金が使われるのだろうということでございますが、これは保護者会でもご説明しておりますけれども、すまいるスクールにかかわる経費の中の一部を保護者の方にご負担していただくという考え方ですので、上げた分をＡなり、Ｂなり、Ｃなりに充当するということではなく、全体の事業の中でのご負担の割合を一定額にしていただくという考え方でございます。ですので、上げた分は、すまいるスクールの運営に充当してまいります。"},{"i":345,"speaker":"石田（ち）委員","text":"今、登録料と保険料のところの１,２００円というのは、年間に１,２００円かかっていたというのは、私たちも承知しているのです。でも、利用料はかかっていなかったわけです。それを、有料化するわけです。値上げではなく、有料化にするのです。なので、そこに対して受益者負担ということだったのですけれども、保育料も上がって、すまいるスクールも有料化、そして６時までの人は３,２５０円、７時までの人は４,２５０円という大幅値上げを到底受け入れられないと私は思うのです。これだけの値上げが負担になるとは感じないのでしょうか。"},{"i":346,"speaker":"伊崎子ども育成課長","text":"今現在の利用料の考え方ですけれども、参加費としてという捉え方でいらっしゃいますけれども、これはすまいるスクールを利用するための費用としていただいているものでございます。言いかえますと、来年度からは５５０円の、今おっしゃられている参加費というものがなくなりまして、利用料という形で月額に変わってくるということでございます。\nあと、保護者の方のご負担という意味合いでございますけれども、ご負担いただく金額が増えることは、お一人お一人の受けとめ方としては、負担が増えるという受けとめ方をされるというのは、否定するものではございません。ただ、この中でも、その金額が負担となってすまいるスクールに参加できないということがないように、今減額・免除の対象を検討しているところでございますので、そこは考慮しております。"},{"i":347,"speaker":"石田（ち）委員","text":"その有料化によって利用できなくなる人がいないように減免措置を考えているということなのですけれども、だったら今までどおりでいいのではないかと思います。この間、値上げの根拠なども、学童保育クラブに合わせて３,０００円にしたり、ほかの地域と比べて、ほかの自治体と比べてもというお話なども出されているのですけれども、やはり学童保育との比較には私はならないと思います。指導員が午後から半日間しっかりと児童とふれあって学童保育してきたものと、わずか１時間のすまいるスクールの延長料金が３,０００円で同じになるという、本当に比較にならない有料化。そして、それによって参加できなくなるかもしれない子がいるやもしれない状況で値上げをしていく。これも、長い間見直しをしてこなかったというところで、今回は延長もするし、おやつも出すし、値上げをする、有料化するというお話だったのですけれども、そういった比較にならない金額、算定根拠などを見ても、有料化はやめて、今までどおり子どもたちが、そして親たちも安心してすまいるスクールに通わせることのできる制度にしていくべきだと思います。\n改めて、私も中止を求めますけれども、いかがでしょうか。"},{"i":348,"speaker":"伊崎子ども育成課長","text":"まず、学童保育との比較にならないというご指摘でございますが、すまいるスクールはほかの児童クラブと放課後子ども教室の両方を一体的に実施している事業でございます。ですので、当然学童保育であり、放課後子ども教室でもございまして、その中で１時間で幾らという考え方ではなく、延長をご利用する方については１時間の延長で３,０００円をいただくという考え方でございますので、それは１時間分の職員のコストに対する経費ということではございません。先ほど申し上げましたように、すまいるスクール全体の経費に対するご負担と考えていただければと思います。\n今回の見直し等々につきましては、既に条例でご可決いただいているところでございますので、来年度４月の実施に向けて準備をしているところでございます。"},{"i":349,"speaker":"飯沼委員","text":"今のすまいるスクールのところなのですけれども、学童保育のところは１時間だけではなくて、全児童と学童保育と両方やっているというご答弁をたびたびいただいているのです。私はよく職員の方の中身をいろいろ伺っているのですが、職員の方は目の前にいる子どもと親の顔が一致しない。親が浮かばないというのです。この子の親御さんがどういうお仕事をしていたり、家庭の事情がどうなのか。この子が抱えている生活の背景が見えないと言うのです。とても優秀な指導員の方なのですけれども、私は決定的にここが以前の学童保育と今のすまいるスクールとの違いであると思っているのです。\nだから、すまいるスクールに通っていけば、安全に過ごせるように指導員なり、委託の方が見えて、安全を確保はしてくれる。でも、その子がどういう状況を抱えて、何を求めてそこにやってくるのかというのを、毎日同じ指導員の方が確実にいて、いつもその子を見つめていてくれたらわかるかもしれないけれども、決してそういう状況ではないと職員の方がおっしゃっているのです。私は、これは特殊な例ではなくて、多分職員の方に伺ったら、皆様そう答える。一人ひとりの子どもの状況をつかむ仕事ではないのだと。委託で来ている方たちとどううまく時間をやりくりして、１日けがなく終わったらいいのかというところで精一杯だと言っていて、私は我が子を学童保育に預け、先生とも面談をよくやっていただいたし、保護者会にも行ったり、親御さん同士のつながりも持っていましたけれども、話を聞くと全然違うのです。\nだから、課長がいくら学童保育を包含していますとおっしゃっても、それに当たらない。私はぜひそこのところを現場の職員の方もそうですが、親御さんたちに学童保育とはというのもちゃんとお伝えしていただきたいと思うのです。保護者会にもほとんどいらっしゃらない状況の中で、今、親御さんとつながる手立てを、指導員の方は多分持っていないのだと思うのです。そういった状況の中に子どもが置かれているという現実を見て、たびたび学童保育をやっていますとおっしゃるのは、私は現実とあまりにもかけ離れていると思っています。\nいい機会でもあるので、すまいるスクールをもう一回見直していく。学童保育を必要とする子がどれだけいて、どういう要求があるのかというところもしっかりつかんでいただきたいと思っています。\nこれは、今流れを聞いていて一言言いたかったので、聞いていただければ、とりあえずお伝えしておきます。\nあと、幼稚園も保育園もそうなのですけれども、保育料は値上げではないとおっしゃったのだけれども、値上げなのです。おおむね約１０％の値上げということで、個々に違うということなのです。\n１つ、説明会はどのようにされたのか、するのか。一人ひとりが問い合わせをすれば、どういうふうに変化するのかわかるのですか。そこのところ、多分親御さんたちは、この状況が伝わる中で自分はどうなるのかというのが最も関心が強いので、一人ひとり違うとおっしゃって、この間モデルもなかなか出せないということだったのですが、一人ひとりが我が家はどうなるのかというのを知りたいのですけれども、説明はどうするのか。一人ひとりがわかる状況なのか、そこを教えてください。"},{"i":350,"speaker":"竹田保育課長","text":"在園児の方については、それぞれの施設を通じてご説明させていただいております。また、施設長会等を通じまして、施設の長には私どももご説明させていただいているところでございます。\nなおかつ、ご質問のある方については、保育課のほうにお問い合わせをいただいているところでございます。"},{"i":351,"speaker":"飯沼委員","text":"在園児の方に対しては、施設というと、園長先生が説明をする。説明会みたいにして行っているのですか。文書を配る。どういう形なのか。あと、保育課のほうにはどのくらいお問い合わせが具体的にあるのか教えてください。"},{"i":352,"speaker":"竹田保育課長","text":"広報紙にも詳細を載せておりまして、そういったものを通しまして、保護者の方には園からご説明いただいているところでございます。\nお問い合わせの数はカウントしてございませんので、正確な数は把握しておりません。"},{"i":353,"speaker":"飯沼委員","text":"ぜひカウントしていただきたいし、どういう状況なのかも、ぜひ実態を教えていただきたいと思います。保育料値上げの話を聞くと、まずびっくりされるというか、やはり今の社会情勢の中で、とても負担感が大きい。一番には、どうして子育てを応援してくれないのかという、これは圧倒的な声なのです。生活が大変な中、それでも高い税金をすごく苦労して払っているのに、どうして値上げするのか。なぜなのだろうと、なぜがいっぱい飛び出している。すごく良心的な方は、保育料を上げると、子どもたちの環境がよくなるのですか、もっと環境がよくなるのですか、また保育士さんの給料が上がるのですかと、私はすごく率直な、それだったらという思いも多分おありなのだと思うのですが、そういう方もおられます。こういった声を聞いて、お父さんとお母さんの置かれている状況、実態をどう受けとめますか。皆様それぞれ、能力の範囲で税金を払っています。そして、必要に応じて税金というものは使うものなので、税金は本当に必要なところに使ってほしい。これが声なのです。\nそれで、たびたび言っていますが、基金がたまっています。税収が増えています。子育て世代も増えています。品川区に税金を納めています。この税金をぜひ子どもたちに使ってほしい。私は、これは当然な当たり前の声だと思うのですけれども、どうしてこうならないのでしょうか。教えてください。"},{"i":354,"speaker":"竹田保育課長","text":"児童１人当たりの平均月額は２万３,５７９円でございます。保育料です。運営費全体に占める利用者の負担割合は、平成２６年度現在、１５.４％となっておりまして、前回の全保護者を対象とする保育料の改定から１０年以上経過していることから、今回の保育料の改定は必要不可欠なものだと認識しております。"},{"i":355,"speaker":"塚本委員長","text":"飯沼委員、少し質疑が長引いておりますので、まとめていただくようお願い申し上げます。"},{"i":356,"speaker":"飯沼委員","text":"運営費負担割合が１５.４％、私はすごく高いと思います。これを安いというのは、やはり国の基準のところに照らし合わせるからなのです。国が子育てにお金をちゃんと使っていないというところも、しっかり言っていっているといつもご答弁がありますけれども、そこにも責任はありますけれども、だからといって、それを保護者に負担をかぶせていくというのは、明らかに間違いであると思います。\nあと、皆様にぜひ考えていただきたいのは、受益者負担という言葉は、子育て支援に全く合わない、ふさわしくないと思うのです。子どもを産める人が産んでくれなかったら、将来本当に少子化がどんどん進んで、先ほど２人から３人子どもを産みたいという人たちが、本当に安心して子どもが産めるといったら、やはりお金の負担がない社会。それを社会全体で支えていくというのが、私は福祉国家であると思って、それを目指してほしいし、お金がないのだったら、みんなで何かを考えなければいけないけれども、財源がどんどんたまっていて、使えるお金があるのに使わない。これは本当になぜと、何回言っても納得できないことであると思うのです。\nなので、社会全体で子育てを応援しようという社会にしていこうという合意ができれば、十分品川区はできると思うので、私は行政のほうへはたびたび求めていますが、ここにいらっしゃる同僚の委員にもぜひ応援してくれる社会になってほしいと思うのですが、いかがでしょうか。私はぜひ応援していきたいと思っています。"},{"i":357,"speaker":"塚本委員長","text":"ほかにご発言ございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":358,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、質疑を終了いたします。\nそれでは、平成２７年請願第３２号、認可保育園・区立幼稚園保育料値上げとすまいるスクール有料化の中止を求める請願について、ご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらか、まず、自民党・子ども未来からご発言願います。"},{"i":359,"speaker":"鈴木（博）委員","text":"結論を出す。"},{"i":360,"speaker":"浅野委員","text":"結論を出す。"},{"i":361,"speaker":"飯沼委員","text":"結論を出します。"},{"i":362,"speaker":"大倉委員","text":"結論を出します。"},{"i":363,"speaker":"高橋（し）委員","text":"結論を出します。"},{"i":364,"speaker":"塚本委員長","text":"それでは、本件については、結論を出すでご意見がまとまったようですので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":365,"speaker":"塚本委員長","text":"それでは、本件については、結論を出すに決定いたしました。\n採決に入ります前に、本件につきまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":366,"speaker":"鈴木（博）委員","text":"少子化対策に確実に対応していくためには、ある程度の合理的な負担は必要です。したがって、ある程度の負担はやむを得ないと考えて、それをどうやって過不足なく合理的に組み立て、持続可能にしていくかが問題だと思います。\nこの間の区の説明に関しては、私たちの会派も十分納得したし、賛成いたしました。今、この請願を見てみると、例えばすまいるスクールは無料で利用できるとか、一部そうなのかというところもあるので、その辺はしっかりと区のほうも説明が必要なのではないかと思います。\nだから、私たちはこの請願そのものは不採択でお願いしたいと思うのですが、それと同時に、区にも十分な説明を各利用者の方にしていただいて、誤解や情報不足のために理解が十分されていないようなところに関しては、十分な説明をするように要望したいと思います。"},{"i":367,"speaker":"浅野委員","text":"不採択です。\n値上げというところで中止、中止ですけれども、応能負担という部分を考えていくならば、今後の負担増と言われる部分もありますけれども、適正な使用料というものが必ずあると思いますし、保育料でもありますので、それはぜひともある程度確保しながら、子育て支援を進めていただきたいと思います。\nそれと、すまいるスクールですけれども、こちらについては減免を検討しているという話をいただきましたので、来年４月からスタートできるように、今検討されていると思います。また情報システムの関係もあるならば、あまり時間がないとも思いますので、きちんとスタートしていただければと思いますので、また報告いただければと思います。"},{"i":368,"speaker":"飯沼委員","text":"一言言って、採択を主張したいと思います。\n子育てへの経済的負担軽減、これはなくてはならないものであると思っています。安心して子どもを産み育てられる品川区にしていくためにも、応援していくという意味で採択を主張します。"},{"i":369,"speaker":"大倉委員","text":"不採択でお願いします。\n適切な認可保育園の運営という部分においても、区からお話を伺ったところにおいては、納得できるところであります。今までもさまざま議論がされて決定されたことでありますので、今回の請願については不採択でお願いしたいと思います。"},{"i":370,"speaker":"高橋（し）委員","text":"不採択でお願いします。\n先ほども出ていましたけれども、全体的な区の政策の中での整合性というところ、それは合理的な理由、あるいは応能負担といったところが理由だと思います。\nそして、改定の際に保育料のほうではさまざまな減免について、そしてすまいるスクールのほうは今後検討するということですので、そのあたりは確実に政策、制度として実行していただくことを要望いたします。"},{"i":371,"speaker":"塚本委員長","text":"それでは、平成２７年請願第３２号、認可保育園・区立幼稚園保育料値上げとすまいるスクール有料化の中止を求める請願について、採決をいたします。\n本件は挙手により採決いたします。\n本件を採択とすることに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":372,"speaker":"塚本委員長","text":"賛成少数につき、平成２７年請願第３２号は不採択と決定いたしました。\n────────────────────────────────────────────\n(3) 平成２７年請願第３３号 一人ひとりの子どもが大切にされる品川区を求める請願"},{"i":373,"speaker":"塚本委員長","text":"次に、(3)平成２７年請願第３３号、一人ひとりの子どもが大切にされる品川区を求める請願を議題に供します。\n本件は、初めて取り上げますので、書記に朗読させます。\n〔書記朗読〕"},{"i":374,"speaker":"塚本委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者の説明を求めます。"},{"i":375,"speaker":"今井待機児童対策担当課長","text":"それでは、私から本請願の項目についてご説明いたします。\n初めに、請願項目の１についてでございますが、品川区ではこれまでの認可保育園の新規開設や定員の弾力化を大きな柱として、保育の受入枠の拡大を進めているところでございます。待機児童の解消は区の重要な政策目標の１つでございますので、認可保育園、小規模保育事業、認証保育所などの開設による総合的な待機児童対策を引き続き進めていく姿勢に変わりはございません。\n次に、請願項目２についてでございますが、認可保育園、小規模保育事業などの地域型保育事業、認証保育所などの保育施設について、その屋外遊戯場、そしてその代替地となる公園や広場につきましては、それぞれの基準や要綱等により設置しておりまして、代替地である公園等を活用し、適切な保育が行われているものと考えております。\n最後に、請願項目３でございますけれども、平成２７年４月現在でございますけれども、品川区内には区立公園としまして、公園等が１４７カ所、それから児童遊園が６７カ所のほか、防災広場などをあわせて、２６３の区立公園等があるところでございます。公園は小さな子どものほか、高齢者を含めさまざまな世代や目的を持った方が集う公共スペースでございますので、子どものアイデアを活かした公園などの取組みも公園課で進めておりますが、引き続き地域住民利用者の声をいただきつつ、幅広い需要を踏まえて整備を進めていくものでございます。"},{"i":376,"speaker":"塚本委員長","text":"説明が終わりました。\nこれより質疑を行います。ご発言願います。"},{"i":377,"speaker":"飯沼委員","text":"一人ひとりの子どもが大切にされる品川区を求める請願は、毎年出されています。皆様多分ご存じだと思いますけれども、本当に毎回出るということは、願いが叶っていないということなのです。今しっかりとご覧になっていらっしゃると思うので、ぜひ元気な子どもの声が響き渡る品川区になってほしい。一人ひとりが大切にされることを求める請願なので、共産党は多く紹介議員になってしっかり受けとめていますので、ぜひ皆様にもしっかり受けとめていただいて、ご発言をお願いしたいと思っています。\n私は、１点目の認可保育園の増設を行ってください。待機児童の解消について、私はこの１点で訴えたいと思いますが、区はさまざまな施策で頑張っていらっしゃると思います。現場の方々も、本当にしっかりと子どもたちを見てくださっているというところはありますけれども、皆様もご存じだと思いますが、まちを歩くと認可外の保育園が次々にできているのを、多分ご覧になっている。きのうまでオフィスだったところに、前にカウンターみたいなものができて、カーペットが敷かれ、外の狭いところに４人乗りの乳母車が幾つも並んでいるという状況。本当に狭い路地を歩くと、ここにもできた、ここにもできたという感じで、認可外の保育施設が次々にできています。\nお父さんやお母さんやおばあちゃんたちもそうなのですが、こうやって請願項目の中にあるように、本当に認可保育園をつくってほしい。本来、保育園は認可保育園と無認可も昔はありましたけれども、その２通りだったのが、今は国と自治体が税金投入をそこに絞っている。主に国が投入する金額が少ないからだと思いますけれども、認可保育園の増設がなかなか進まないということですが、私はどの子も等しく大切にされる品川区であったら、やはり国基準で守られている認可保育園。国基準で守られているというところ、当たり前なのです。\nそういった意味で、私が今日、強調したいのは、子どもの命がかかっているというところで、このところ、結構死亡事故の記事が出たりするのですけれども、皆様ご覧になったと思います。ここに統計が出ているのですが、２００４年から２０１４年に全国の保育所で起きた事故のうち、少なくとも１６３人の子どもが死亡しており、そのうちの約７割が認可外保育所で起きていることがわかりましたということで、日本経済新聞５月７日のところで書かれています。２０１４年４月１日時点の待機児が２万１,３７１人。減らない中で、市場競争の中で、認可外の保育所が増えている。決してよくない、恵まれていない施設もあるし、そこで働いている保育士は、本当に劣悪な条件ですぐ辞めてしまうというところもあるし、ところによっては経済的に難しくて閉鎖されてしまうところが生まれています。\n私は本当に命を守れない保育所ではどうしようもないです。命を守るというために、お母さんたちは認可保育園を求めている。ここのところをしっかり受けとめたら、さまざまな施策をやっていますということで通過はできないだろうと思っています。ぜひ認可保育園をしっかりと柱に据えていくということを自治体は肝に銘じるべきだと思うのですけれども、この１点でいかがでしょうか。"},{"i":378,"speaker":"今井待機児童対策担当課長","text":"認可外保育施設ということなのですけれども、まず確認させていただきますが、明日の総合的な待機児童対策の資料にもあるところで、これまでもご説明していますけれども、東京都の認証保育所というのは、東京都の基準に従って設置、指導されているものですので、これは子どもの安全・安心を守る基準がきちんと担保されております。\nそして、小規模保育事業につきましては、区の認可事業として、今年の平成２７年４月から国の基準に基づいて、改めて区が認可の基準をつくりまして、同じく子どもの命、安全、健康に育つ基準というところでつくっている認可事業になりましたので、いわゆる総合的な待機児童対策の中で、委員もいろいろなとおっしゃいましたけれども、全てこれらの施設、事業については子どもの安全・安心を守るための設置基準、それぞれに基づいてやっている施設、事業ですので、誤解のないようお願いいたします。"},{"i":379,"speaker":"飯沼委員","text":"私は誤解しておりません。余分な言葉をつけないでいただきたいと思います。私はどの施設も見学していますし、身近なところは重々知っています。違いもわかっています。認証があったり、区で認可をしているからといって、同等の水準ではないです。そこのところをどう捉えて、都が認証しているから、区が認可をしているから、それで認可保育園と同等であるというのは間違いだと思いますけれども、そこの認識はどうなのでしょうか。"},{"i":380,"speaker":"今井待機児童対策担当課長","text":"まず、認証保育所でございますけれども、今、品川区内にＡ型、Ｂ型等ございますけれども、Ａ型の保育施設という形で開設補助金を入れているところは保育士が１０割、それから、現在、小規模保育事業につきましても、いろいろ去年の審議の中でご議論ありましたけれども、全てＡ型でやっておりますので、保育士も１０割、さらに小規模につきましては、面積基準が国よりさらに品川区の場合、以前の家庭的保育事業と同じにしまして、保育の１人当たりの面積を３.３m2とっているなど、認可保育園と同等な保育施設の基準、または保育士の基準で運営されていると認識しております。"},{"i":381,"speaker":"塚本委員長","text":"まとめていただけると。"},{"i":382,"speaker":"飯沼委員","text":"あまり長くしたくないのですけれども、答弁が答弁なので、黙っているわけにはいかないということになってしまうのです。\n今の答弁があるから、認可保育園と同じかという質問には全く答えていないのと、私はすごく施設をよく知っています。経営者も知っています。働いている人も知っています。一番に違うのは、施設環境も違いますけれども、働く職員が違うのです。はっきり言って、賃金が違う、保障が違うといったことで、一番にはころころ変わってしまう。よりよいところに変わってしまう。私の知っている人もすごく変わっていますけれども、あとは表向きと中身が違う。これは事実なのです。資格がある人が、認証は１００％、１０割保育士だといっても、どこもこれで確保されているかと思ったら、実態は違うのです。表向きで見るのは当然でしょうけれども、公立のところにおいて、非常勤で入っている部分は別としても、正規でしっかり確保しているところに偽りはないと思うのですが、認証保育園や認可外のところの表向きと実態が違うというのはあります。\nあと、先ほど私が言ったのですけれども、とにかく命を守るという意味では、統計的に認可外のところで死亡事故やけがが多いのです。これは歴然とした事実。やはり親はここでびびります。かわいい我が子を一生懸命育てて、認可保育園に預ける手前で、働かざるを得ないからどこででもと預けて、そこでもし命を奪われるようなことがあったら一大事です。その責任は、選んだ親にあるわけではないと思います。やはりきちんとした受け皿を自治体がつくる。私は認可を柱にしていくことが、まず大前提であると思うのですが、さまざまなところではなく、本当に認可で増設を考えていただきたいと思います。\nこれ以上やりとりしても長くなるので終わります。"},{"i":383,"speaker":"石田（ち）委員","text":"私は園庭のところで少しだけ。この間、保育所に公園アンケートをとっているということで、それは国家戦略特区でしたか。都市公園に認可保育園を設置することができるためのアンケートだということだったのですけれども、保育園の公園利用の実態というのは、とってきているわけですので、どういった保育園がどれだけの公園を使っているというのがわかったのではないかと思うのですけれども、その辺、今どんなところまで進んでいるかを伺いたいのです。"},{"i":384,"speaker":"今井待機児童対策担当課長","text":"今回のアンケートにつきましては、委員ご案内のとおり、品川区内の保育園だけではなく、幼稚園、そして認可外保育施設にもアンケートをとったところです。主要な目的は、実際に公園をどのように利用されているかを踏まえて、公園の中に保育園の設置を検討していくものでございます。\n現在、まだアンケートを全部まとめ切っておりませんけれども、それを踏まえながら、今までも認可保育園だけではなく、公園は午前中の利用が多いとか、そういう実態としては私どもが認識しているものと変わりはないというところでございます。\n特に、今取り上げてここが課題というところでは認識していないところです。"},{"i":385,"speaker":"石田（ち）委員","text":"公園利用の状況は、区の思っていたものとはさほど違いはないということですけれども、園庭をつくってほしいという理由の中には、この請願文の中にもありますけれども、幼児が体を動かす機会や環境を充実することが、今後の子どもたちの一人ひとりの成長に、生涯にわたって健康の維持のためにも大事だというところで、そういうところからも述べられていると思います。\nこの間、教育のところでも子どもたちの体力が落ちてきている。そういったところで特別なプログラムを組んでいくといったことも始まるわけですので、それはさらに進んでいくという状況にもつながりかねません。やはり健康な、そして体力をこの時期にしっかりと培えるということが大事だと私も本当に思いました。ですので、この間、ずっと園庭は必置義務ではないということを言われているのですけれども、これは区の姿勢や決断でできること、努力でできることだと思うのです。\n先ほども午前中の質疑のひろまち保育園のところで園庭を聞きましたけれども、ＪＲ等々に園庭を働きかける考えはないというはっきりした答えだったのですけれども、本当に子どもたちの成長発達といったところを考えたときに、区の姿勢、そして、どう決断して、どう交渉するのかというのは本当に大事なことだと思うし、その発言を聞いて冷たいと感じたのです。\nですので、今後つくっていく認可保育園には園庭をつくっていくということを、区の姿勢として持っていただきたいと思うのですけれども、いかがでしょうか。"},{"i":386,"speaker":"今井待機児童対策担当課長","text":"園庭、いわゆる国、または私どもの要綱で言う屋外遊戯場でございますけれども、これは屋外活動という形で、必要なものであるということは、保育所保育指針にも書かれているところでございます。ここは、否定するところではございません。\nただし、それを区立および私立に対して、全てが設置を義務づけるということは、一方であります待機児童解消のための新規開設の妨げにもなりますので、必置を求めることはございません。\n屋外遊戯場のかわりとなる公園またはそれぞれの保育の室内、または屋内のホール等で体を動かすなどの取組みについて、また保育園とその辺は検討していきたいと思っております。"},{"i":387,"speaker":"石田（ち）委員","text":"そういった園庭がないために、いろいろな公園に子どもたちが遊びに行く、たびたび毎日遊びに行くという状況で、どの公園も渋滞だという状況ですので、やはりつくってくださいというのが請願項目です。ですので、ぜひここに区の努力で応えていただけるようにしていただきたいと思います。\nそれと、１１月１日号の広報しながわで、先ほどの保育料のところで聞けばよかったかと思うのですけれども、保育料の改定をしますというお知らせの中に、「区は待機児童対策を緊急課題として、受け入れ枠の拡大を実施してきましたが、開設経費や運営経費も増大しています」と書かれているのです。そうすると、保育料の値上げをしたことで、待機児対策がぐんと進むということとして受け取っていいのかどうか確認したいのです。"},{"i":388,"speaker":"今井待機児童対策担当課長","text":"まず、保育園の新規開設でございますけれども、こちらは開設経費、そして横に保育園運営経費と出ておりますけれども、それを総合的に勘案して開設数を判断するとともに、それだけではなく、本会議でも答弁していますように、新たな人口推計の結果が出ましたので、それを踏まえて改めて乳幼児人口、そして入園者の申込率を含めて開設をしていく形になっております。\n保育料の決定につきましては、保育園運営経費、待機児童に伴う新規開設が当然保育料に反映していっているものだと考えております。"},{"i":389,"speaker":"塚本委員長","text":"石田委員、そろそろまとめていただきたいと思います。"},{"i":390,"speaker":"石田（ち）委員","text":"そうですね。\nそうすると、保育料から増設に回るお金というのは、大体何割ぐらいになっていくのでしょうか。つくっていく数で違うとは思うのですけれども、大体１園増設するのに、保育料からかかるのはどれぐらいになるのか、わかれば教えてください。"},{"i":391,"speaker":"今井待機児童対策担当課長","text":"先ほど、保育課長が答弁申しましたとおり、運営費の１５％が保護者負担です。ここに開設の経費が全て保育料の負担に入っているということではないです。全体の経費の中で今後検討していくものだと考えておりますので、何園つくったから幾ら上がるという単純計算ではないです。"},{"i":392,"speaker":"高橋（し）委員","text":"先ほど、認証保育園で区のルールと違うことをやっていて、表と裏は違う、実態は違うというお話があったのですが、仮にそうだとすれば、それを区はホームページでも紹介し、保育案内にも載せているわけなのです。それで、補助金も納めているということなのですけれども、それは本当かと思ったのですが、そういう事実があるとして、詰められているのでしょうか。新年度の認証も含めてそういうことになると思いましたが、その点はいかがでしょうか。"},{"i":393,"speaker":"今井待機児童対策担当課長","text":"東京都の認証保育所の立ち入りにつきましては、東京都も新規開設して、すぐ３カ月以内に立ち入った後に、１年の中でもう一回、東京都と品川区が見る形になっております。\n先ほどの委員のお話の中で、明確にどこの認証保育所というご提示はございませんでしたけれども、そのような認証保育所がございましたら、私どもは速やかに立ち入りの検査等をしていきたいと思っております。"},{"i":394,"speaker":"伊藤副委員長","text":"先ほどの質疑の中で、認可保育園でなければ命を守れないという話があったのです。これは非常に失礼な話です。認証やその他のさまざまな保育園の方々が、一生懸命品川区のことを考えてやっているにもかかわらず、そういうふうに捉えられるような表現をしたということについては、やはり議会として品川区の見解を確認していただきたいと思うのですが、ご答弁をお願いいたします。"},{"i":395,"speaker":"今井待機児童対策担当課長","text":"先ほども申しましたとおり、認可保育園、小規模保育事業、認証保育所、それぞれ大もとは保育所保育指針でございますけれども、それぞれの基準、通知、要綱に基づいて、適切に子どもと安全、そして健やかな発達を保障するための保育を実践しているところでございます。"},{"i":396,"speaker":"伊藤副委員長","text":"確かに認可保育園も頑張っていらっしゃるけれども、民間の方々も頑張っていらっしゃるわけです。だから、そこのところをしっかりと理解した上でないと、品川区のさまざまな保育施策ができないと思う。ただただ認可だけがよくて、それ以外はだめだということからすると、今の発言が出ると思われますので、それは議会としてしっかりと指摘していきたいと思います。\nそれから、品川区のゼロから５歳の子どもが平成２７年時点で１万８,７３３人いるわけで、保育園に入ったのが６,９２１人。ずっとこの議論を聞いていて思うのは、何も保育園や区立の保育園、幼稚園等々に入った子どもだけを守ろうとすることは間違いだと思うのです。もちろん区立にかかる子どもたちを守っていく。だけど、差引き１万２,０００人余の子どもたちのことも品川区としては考えていかないといけない。\nそうなると、何も待機児童の解消は認可保育園の増設だけではなくて、繰り返し言っているけれども、さまざまな保育施策を総合的に展開をしていって、税金の有効活用からすれば、１万２,０００人の子どもたちについても品川区は責任を持っていくべきだし、それから、より多くの納税者の方々のことを考えていくと、何も認可保育園だけを錦の御旗にすることはないと私たちは思う。さまざまな方法を展開していって、税の有効活用をすると同時に、保育園や幼稚園に通っていない子どもたちに対しても、品川区としてはさまざまな保育の環境を準備していくべきと考えますが、いかがでしょうか。"},{"i":397,"speaker":"今井待機児童対策担当課長","text":"委員ご指摘のとおり、これは国の議論でもご発言があったところなのです。３歳、４歳、５歳は何らかの幼稚園、保育園、幼児教育施設、保育施設に通っていらっしゃいます。一方がゼロから２歳児に関しましては、在宅で子育てしていらっしゃる方も多いところでございますので、品川区としましては、明日ご説明させていただきます、私立幼稚園、区立幼稚園の預かり保育ですとか、また在宅子育てのための預かり、生活支援型の事業ですとか、そういうものも含めて大きく視野を持って進めていきたいと考えております。"},{"i":398,"speaker":"伊藤副委員長","text":"よろしくお願いします。"},{"i":399,"speaker":"塚本委員長","text":"では、ほかにご発言がないようですので、質疑を終了いたします。\nそれでは、平成２７年請願第３３号、一人ひとりの子どもが大切にされる品川区を求める請願について、ご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらか、自民党・子ども未来からご発言願います。"},{"i":400,"speaker":"鈴木（博）委員","text":"結論を出す。"},{"i":401,"speaker":"浅野委員","text":"結論を出す。"},{"i":402,"speaker":"飯沼委員","text":"結論を出します。"},{"i":403,"speaker":"大倉委員","text":"結論を出します。"},{"i":404,"speaker":"高橋（し）委員","text":"結論を出す。"},{"i":405,"speaker":"塚本委員長","text":"それでは、本件については、結論を出すでご意見がまとまったようですので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":406,"speaker":"塚本委員長","text":"それでは、本件については、結論を出すに決定いたしました。\n採決に入ります前に、本件につきまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":407,"speaker":"鈴木（博）委員","text":"まず、今、伊藤副委員長もおっしゃったように、私たちは保育の重要性と保育園で子どもが健やかに安全に育つことは非常に大切だと考えています。\nただし、認可保育園の先生たち、保育士の人たちも一生懸命やられて、非常に子どものために献身されていると思うのですが、認証保育所でも小規模、家庭的保育事業でも、そちらに勤めている方たちは、子どものために考えて、一生懸命子どもの養育をされていると思うのです。\n保護者のほうも、いろいろと選択の幅が広がるということは、例えばライフスタイルや仕事上からもいいことだと思うのです。\nだから、私たちは認可保育園を非常に重要で大切なものだと考えていますが、別にほかの認証保育所や小規模保育など、ほかの企業内保育所もそうですけれども、やはり大切な位置づけをして、総合的に子ども・子育て支援の施策が進むことが重要だと考えておりますので、まず１点、違和感を覚えるところです。\n２番目に、屋外遊戯場は非常に大切で、この請願書にも書いてあるように、幼児期は体力を培う上で非常に大切な時期であり、運動や遊びの中で十分に体を動かす必要があるということに全く異議はないのです。それが、保育園には園庭が不可欠であることと直接的に結びつくというのが、よくわかりません。確かに屋外遊戯場というのは大切なもので必要だから、あるに越したことはないのですが、今の東京の状況で、全てに屋外遊戯場が完備された保育園をつくるということは現実的に不可能だと思うので、それに越したことはないのですけれども、今、子ども未来部で一生懸命待機児童対策で保育園をつくられている努力を私は大変評価するし、その中で、屋外遊戯場をできる限りのことで考えながら施策を遂行するということに関しては、それは非常に評価しております。\nそれと、最後に保育園をたくさんつくってほしいという３番目なのですが、これは当然のことでありまして、これに関しては品川区も今後努力されればいいのではないかということで要望します。\n以上、まとめますと、不採択でお願いします。"},{"i":408,"speaker":"浅野委員","text":"待機児童の解消、認可保育園の増設を行ってくださいとありますけれども、やはり今まで区が進めてきました認可保育園も当然増やしていく中で、認証保育所や小規模保育事業など、さまざまな選択肢と言ったらおかしいですけれども、事業者の選択肢が増えてきているということもありますし、このような手を活用してというのでしょうか、利用して待機児童対策をこれからも進めていっていただければと思います。\n園庭については、確かにあったほうがいいというのは事実でありまして、今自民党・子ども未来からも話がありましたとおり、やはり努力はしていただくにしても、場所の問題を考えますと、今の品川区の状況がかなり厳しい中で、事業者もうまく工夫して対応されていると思います。そういう意味では、支援していっていただければと思います。\nあとは、公園広場など、環境整備といいますと、これは直接は文教委員会とは違ってくる、子ども未来とも違ってくるところがあるかと思いますけれども、区としては進めているところでありますので、これも継続して品川区の魅力というものを発信していっていただければと思います。そういう観点から不採択です。"},{"i":409,"speaker":"飯沼委員","text":"意見を添えて採択を主張します。\n先ほどの他の委員の発言なのですが、人の発言を曲げて表現するような手法はやめていただきたいということを１つ言っておきます。\nあと、待機児対策、命を守るために国基準、国が責任を持つ認可保育園を柱に据えてほしい。これは当然と思います。あと、心身ともに元気に成長するのに、園庭、公園はなくてはならないものであるということをしっかりと受けとめていただきたいと思います。\n採択を主張します。"},{"i":410,"speaker":"大倉委員","text":"請願については不採択でお願いいたします。\n今、まさに待機児童対策は本当に重要な取組みでありますので、早く、できるだけ多くの望んでいる方に入っていただきたいと思っておりますが、認可保育園だけではなくてさまざまな選択肢がある中で行っていくこともスピーディーかつ柔軟性を持ってやっていくということは非常に大切だと思います。品川区でも、多くの取組みをする中で、対応してくださっていると思っております。\n園庭についても、皆様おっしゃっていますが、あるに越したことはないですが、なかなか品川区の現状から考えると難しいという部分でありますので、そういったもろもろを含め、不採択でお願いしたいと思います。"},{"i":411,"speaker":"高橋（し）委員","text":"不採択でお願いします。\n１番の認可保育園でということですが、待機児童対策のこれまでの流れを見せていただくと、認可保育園の定員拡大が柱で、そしていろいろな事情、さまざまな条件において、小規模保育事業、認証保育所を誘導しているという政策は、いただいた資料からもわかります。\n認証保育所に関しては、先ほど少しお話がありましたけれども、あたかも認証保育所がルールのあれではないということは、真面目にきちんとやられている認証保育所の方々からすれば、認証保育所は少しあれなのではないかという印象になってしまい、実際にしっかりやられている方々が多いので、児童の受入先として十二分対応できていると思っていますので、数々、いろいろな種類で対応しているということです。\n園庭については議論がありましたけれども、そういった事情でなかなかつくれない場合は、本当に安全を確保して、広場や地域の公園に連れていって、伸び伸びとそこで遊んでもらえるように保育士の配慮を求めます。"},{"i":412,"speaker":"塚本委員長","text":"それでは、平成２７年請願第３３号、一人ひとりの子どもが大切にされる品川区を求める請願について、採決をいたします。\n本件は挙手により採決いたします。\n本件を採択とすることに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":413,"speaker":"塚本委員長","text":"賛成少数につき、平成２７年請願第３３号は不採択と決定いたしました。\n以上で、請願・陳情審査を終了いたします。\n────────────────────────────────────────────\n３ その他\n(2) その他"},{"i":414,"speaker":"塚本委員長","text":"次に、予定表３、その他の(2)その他を行います。\nまず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、文教委員会にかかる項目について、所管質問なさりたい委員がいらっしゃいましたら、その基礎となる一般質問の項目とそれに関する質問内容をこの場でお願いいたします。\nなお、本会議での質問の繰り返しにならないようお願いいたします。\nまた明日、この委員会で理事者からご答弁をいただき、申し出た委員以外の方にも、議論に加わっていただくという形で進めていきたいと思います。\nそれでは、所管質問がございましたら、ご発言願います。"},{"i":415,"speaker":"石田（ち）委員","text":"共産党の南議員の定時制高校のところで、マイスクール八潮の質問で、受け皿になっているのではないかという質問の答弁で、マイスクール八潮だけに限らず、全ての生徒の選択肢に定時制はなっているという答弁だったのです。区としては、定時制高校は存続していくべきだという立場なのかどうかを伺いたいと思います。"},{"i":416,"speaker":"塚本委員長","text":"わかりました。\nそれでは、石田ちひろ委員から一般質問の定時制高校の存続という項目に関して、区の見解をお聞きしたいということでございますので、明日の委員会で理事者の答弁をいただきたいと思います。\nそのほかで何かございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":417,"speaker":"塚本委員長","text":"ないようですので、その他を終了いたします。\n以上で本日の予定は全て終了いたしました。\n明日も午前１０時からの開会でございます。\nこれをもちまして、文教委員会を閉会いたします。\n○午後 ５時５７分閉会"}]});
